1	/*
2	 * Step grouping tests (Group G2).
3	 *
4	 * Loaded by tests/frontend/test_app_pure.mjs after its shared DOM stub is
5	 * installed. Exposes `registerStepGroupingTests({app, check, findOne,
6	 * findAll})`.
7	 *
8	 * Coverage:
9	 *   (a) All records sharing one step_id — step_started + conversation +
10	 *       step_output + step_completed — collapse into a SINGLE visual step
11	 *       region (exactly one .history-step-header), in strict timestamp order.
12	 *   (b) step_completed / step_failed / step_output do NOT spawn a second,
13	 *       same-named step region.
14	 *   (c) A genuinely different step_id DOES start a new region.
15	 *   (d) The incremental-append path keeps one region (a step_completed
16	 *       arriving after the running anchor does not duplicate the header).
17	 *   (e) Every bubble in a step region carries the shared step-type-<type>
18	 *       identity class for per-step grouping styles.
19	 */
20	import assert from "node:assert/strict";
21	
22	export function registerStepGroupingTests(ctx) {
23	  const { app, check, findOne, findAll } = ctx;
24	
25	  const stepHeaders = (container) =>
26	    findAll(container, "history-step-header")
27	      .map((h) => { const t = findOne(h, "history-step-title"); return t ? t.textContent : ""; });
28	
29	  const startedRecord = (stepId, stepType, ts) => ({
30	    type: "step_started", step_id: stepId, step_type: stepType,
31	    status: "running", timestamp: ts,
32	  });
33	  const chatRecord = (stepId, stepType, role, content, ts) => ({
34	    step_id: stepId, step_type: stepType,
35	    message: { role, content, timestamp: ts },
36	  });
37	  const outputRecord = (stepId, stepType, ts) => ({
38	    type: "step_output", step_id: stepId, step_type: stepType, timestamp: ts,
39	    data: { step: { step_id: stepId, step_type: stepType, status: "running", outputs: {} } },
40	  });
41	  const completedRecord = (stepId, stepType, ts, outputs = {}) => ({
42	    type: "step_completed", step_id: stepId, step_type: stepType, timestamp: ts,
43	    data: { step: { step_id: stepId, step_type: stepType, status: "completed", outputs } },
44	  });
45	  const failedRecord = (stepId, stepType, ts) => ({
46	    type: "step_failed", step_id: stepId, step_type: stepType, timestamp: ts,
47	    data: { step: { step_id: stepId, step_type: stepType, status: "failed",
48	      outputs: {}, error_message: "boom" } },
49	  });
50	
51	  // ---- (a) one step_id → one region ---------------------------------------
52	  check("G2 step_started + chat + step_output + step_completed → one region", () => {
53	    const sid = "07_implement_abcd1234";
54	    const container = document.createElement("div");
55	    app.renderConversation(container, [
56	      startedRecord(sid, "implement", 1),
57	      chatRecord(sid, "implement", "assistant", "working", 2),
58	      outputRecord(sid, "implement", 3),
59	      completedRecord(sid, "implement", 4),
60	    ], false);

