/*
 * Continuous step "lane" background (方案A: 背景连续、块仍分明).
 *
 * Each content-type step-type record paints its --step-lane colour through a
 * z-index:-1 ::before underlay that overflows ±7px vertically. Because
 * .history-detail uses gap:14px between sibling records, two adjacent records
 * of the SAME step each overflow 7px into the 14px gap and meet edge-to-edge
 * at the gap mid-line, so the lane colour reads as one continuous band across
 * the whole step region instead of a stack of disconnected islands. The
 * records' own bubbles / cards / tool markers keep their borders and higher-
 * alpha backgrounds untouched, so the blocks stay individually distinct.
 *
 * Status / DAG markers (.step-status-row / .group-status-marker) are excluded,
 * exactly as the per-type colour rules above.
 */
.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {
  position: relative;
}
.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: -7px;
  bottom: -7px;
  z-index: -1;
  pointer-events: none;
  background-color: var(--step-lane);
}

/*
 * Boundary & container-edge suppression. The ±7px overflow must stay strictly
 * INSIDE one step region: it must never cross a .history-step-header into a
 * neighbouring step, nor bleed into the conversation area's top/bottom padding.
 * This keeps the step-to-step boundary visually identical to before.
 *
 * - First block of a step (right after a header): no upward overflow.
 * - Last block of a step (right before the next header): no downward overflow.
 * - First / last child of the container: no overflow past the container edge.
 *
 * Degrades gracefully where :has() is unsupported: only a 7px same-step tail
 * remains below a step's last block — still never crossing into the next step.
 */
.history-detail .history-step-header + .conv-record::before { top: 0; }
.history-detail .conv-record:has(+ .history-step-header)::before { bottom: 0; }
.history-detail > .conv-record:first-child::before { top: 0; }
.history-detail > .conv-record:last-child::before { bottom: 0; }

