/* SE3 Control Plane — dark theme, CLI-flavoured. */

:root {
  --bg: #1a1b1e;
  --bg-raised: #232428;
  --bg-card: #2a2b30;
  --border: #3a3b40;
  --fg: #d8d9dd;
  --fg-dim: #8a8b90;
  --accent: #4c8dff;
  --green: #4caf6a;
  --yellow: #d6a23a;
  --red: #e0564b;
  --cyan: #3bb6c4;
  --grey: #6a6b70;

  /* Per-step-type grouping accents (G4). A stable, low-saturation, mutually
   * distinguishable hue per StepType, used both for each step region's left
   * rail / faint background lane in the conversation and for the matching
   * step-report card border, so the same step always reads in the same colour
   * across running-flow and history views. Deliberately desaturated so the
   * faint background tints never drop text contrast below AA on the dark
   * surface — status is ALSO carried by text + icon (see step-status rows), so
   * colour is never the sole signal. Adjacent flow steps
   * (discovery→analyze→plan→implement→test→self_check→verify_spec→update_spec
   * →spec_gate→version_analyze→commit→summarize) carry visibly different hues. */
  --step-discovery: #5b8fd6;
  --step-analyze: #3fa9bf;
  --step-plan: #8a82e0;
  --step-confirm: #6f86c9;
  --step-implement: #57a86a;
  --step-test: #3fae9a;
  --step-self_check: #c89a46;
  --step-verify_spec: #d0824e;
  --step-update_spec: #54aec4;
  --step-spec_gate: #c2a13f;
  --step-version_analyze: #a87fc4;
  --step-commit: #79a83f;
  --step-summarize: #828b98;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--bg);
  color: var(--fg);
  font-family: "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
  font-size: 14px;
  display: flex;
  flex-direction: column;
}

h1, h2, h3 { font-weight: 600; }

/* -- top bar -------------------------------------------------------- */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
}

.topbar h1 { font-size: 16px; margin: 0; }

.topbar-right { display: flex; align-items: center; gap: 14px; }

/* -- topbar overflow menu (desktop side) ---------------------------- *
 * The overflow menu (hamburger + #nav-menu wrapper) is a mobile-portrait
 * affordance. To keep the desktop top bar byte-for-byte unchanged, the only
 * rules that touch it on wide screens live here, scoped to >600px so they can
 * never apply to a phone: the wrapper is made transparent (`display: contents`)
 * so its children stay inline flex items of .topbar-right exactly as before,
 * and the hamburger toggle is hidden. The collapse/expand dropdown styling is
 * authored entirely inside the @media (max-width: 600px) block at end-of-file. */
@media (min-width: 601px) {
  .nav-menu { display: contents; }
  .nav-menu-toggle { display: none; }
  /* The Flows-pane "back to machines" button is a mobile-only affordance for
   * the single-view panel switch; on desktop both panes render side by side,
   * so it is hidden here (scoped >600px to never touch a phone). */
  .flows-back-btn { display: none; }
  /* The History detail-pane "back to sessions" button is a mobile-only
   * affordance for the single-view panel switch (G5); on desktop both History
   * panes show side by side, so it is hidden here (scoped >600px to never
   * touch a phone). */
  .history-back-btn { display: none; }
  /* The flow-view sidebar drawer toggle + its backdrop are mobile-only (G4):
   * on desktop the sidebar is always part of the grid, so both are hidden
   * here (scoped >600px to never touch a phone). */
  .flow-sidebar-toggle,
  .flow-sidebar-backdrop { display: none; }
}

.conn {
  font-size: 12px;
  padding: 3px 9px;
  border-radius: 10px;
  border: 1px solid var(--border);
}
.conn-connected    { color: var(--green);  border-color: var(--green); }
.conn-connecting   { color: var(--yellow); border-color: var(--yellow); }
.conn-disconnected { color: var(--red);    border-color: var(--red); }

.se3-version {
  font-size: 11px;
  color: var(--fg-dim);
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
}
.se3-version:empty { display: none; }

button {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 7px 13px;
  border-radius: 5px;
  font-family: inherit;
  font-size: 13px;
  cursor: pointer;
}
button:hover:not(:disabled) { filter: brightness(1.12); }
button:disabled { opacity: 0.5; cursor: not-allowed; }

.icon-btn {
  background: transparent;
  color: var(--fg-dim);
  font-size: 20px;
  line-height: 1;
  padding: 0 6px;
}

/* -- layout --------------------------------------------------------- */

.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(200px, 280px) 1fr;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
}

.machines-pane, .flows-pane {
  background: var(--bg);
  padding: 14px 16px;
  overflow-y: auto;
}

.machines-pane h2, .flows-pane h2 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-dim);
  margin: 0 0 10px;
}

@media (max-width: 720px) {
  .layout { grid-template-columns: 1fr; grid-auto-rows: min-content 1fr; }
}

/* -- machine list --------------------------------------------------- */

.machine-list { list-style: none; margin: 0; padding: 0; }

.machine-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 9px;
  border-radius: 5px;
  cursor: pointer;
  margin-bottom: 3px;
}
.machine-item:hover { background: var(--bg-raised); }
.machine-item.selected { background: var(--bg-card); }

.dot {
  width: 9px; height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--grey);
}
.dot.online  { background: var(--green); box-shadow: 0 0 6px var(--green); }
.dot.offline { background: var(--grey); }

.machine-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.machine-count { color: var(--fg-dim); font-size: 12px; }

/* -- flow cards ----------------------------------------------------- */

.flow-list { display: flex; flex-direction: column; gap: 10px; }

.flow-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 11px 13px;
  cursor: pointer;
}
.flow-card:hover { border-color: var(--accent); }

.flow-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
}
.flow-task {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  font-size: 11px;
  padding: 2px 7px;
  border-radius: 9px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.badge-running   { background: rgba(76,141,255,.2); color: var(--accent); }
.badge-completed { background: rgba(76,175,106,.2); color: var(--green); }
.badge-failed    { background: rgba(224,86,75,.2);  color: var(--red); }
.badge-paused    { background: rgba(214,162,58,.2); color: var(--yellow); }
.badge-init,
.badge-unknown   { background: rgba(106,107,112,.2); color: var(--fg-dim); }

.badge-call {
  background: var(--yellow);
  color: #1a1b1e;
  font-weight: 600;
  cursor: pointer;
}

/* Resume button — inline inside flow cards, history items, and the sidebar. */
.btn-resume {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 2px 10px;
  border-radius: 9px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  margin-left: 6px;
  flex-shrink: 0;
}
.btn-resume:hover:not(:disabled) { filter: brightness(1.15); }
.btn-resume:disabled { opacity: 0.5; cursor: not-allowed; }

/* Resume bar injected below the history detail title. */
.history-resume-bar {
  margin: 4px 0 8px;
}

.progress {
  height: 6px;
  background: var(--bg-raised);
  border-radius: 3px;
  overflow: hidden;
}
.progress-bar { height: 100%; background: var(--accent); transition: width .3s; }

.flow-meta {
  display: flex;
  justify-content: space-between;
  color: var(--fg-dim);
  font-size: 12px;
  margin-top: 6px;
}

/* -- running-flow chat view ----------------------------------------- */
/*
 * A full-screen view (parity with the history view): a sidebar carries
 * Overview / Steps / Machine, the conversation is the scrollable main body,
 * intervention items are pinned above a docked reply box.
 */

.flow-view {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 25;
  display: flex;
  flex-direction: column;
}
.flow-view-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
}
.flow-view-head h3 {
  margin: 0;
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.flow-view-body {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(220px, 320px) 1fr;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
}
.flow-sidebar {
  background: var(--bg);
  padding: 14px 16px;
  overflow-y: auto;
}
.flow-sidebar-content { display: flex; flex-direction: column; gap: 16px; }

/* Main column: conversation scrolls, interventions + reply box are docked. */
.flow-main {
  background: var(--bg);
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}
.flow-conversation {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 14px 16px;
}
/*
 * .flow-conversation reuses .history-detail's flex-column layout. In a flex
 * column children default to `flex-shrink: 1`, which compresses each step
 * block to make the whole stack fit one viewport — combined with
 * .history-step's `overflow: hidden` (kept for rounded corners), that
 * silently crops every step's body to a thin strip. Pin children to their
 * natural height so the .flow-conversation scroller is the one that grows.
 */
.flow-conversation > .history-step,
.flow-conversation > .conv-record,
.flow-conversation > p,
.flow-conversation > div {
  flex-shrink: 0;
}

/* Session token/cost total badge (G4): docked as a non-scrolling thin strip
 * between the conversation and the reply box, with the pill pinned to the
 * left. Deliberately low-key — small dim text, no fill — so it reads as a
 * footnote/角标 and neither obscures the conversation scroll area nor competes
 * with the docked reply controls. Hidden entirely until usage is non-zero. */
.flow-usage-badge {
  flex: 0 0 auto;
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 3px 16px 4px;
  background: var(--bg);
  border-top: 1px solid var(--border);
  color: var(--fg-dim);
  font-size: 11px;
  line-height: 1.4;
}
.flow-usage-badge.hidden { display: none; }
.flow-usage-badge__label {
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.8;
}
.flow-usage-badge__value {
  font-variant-numeric: tabular-nums;
  word-break: break-word;
}

/* -- agent/model badge --------------------------------------------- */
/*
 * A small, unobtrusive badge at the top of assistant conversation bubbles
 * showing which agent produced the response. Displays "agentName · modelName"
 * when both are present, or just "agentName" when only the agent is known.
 * Shown ONLY when the record carries an agent_name field — old records
 * without this field render nothing, no placeholder.
 */
.agent-badge {
  display: inline-block;
  padding: 2px 8px;
  background: var(--bg-alt, #f0f0f0);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--fg-dim);
  font-size: 11px;
  line-height: 1.4;
  margin-bottom: 6px;
  white-space: nowrap;
}

@media (max-width: 720px) {
  .flow-view-body {
    grid-template-columns: 1fr;
    grid-auto-rows: min-content 1fr;
  }
}

/* -- intervention chip-bar ------------------------------------------ */
/*
 * Pending interventions appear inside the docked reply form as a horizontal,
 * wrap-friendly bar of compact chips (kind icon + label + optional short call
 * id). Clicking a chip selects it; the full prompt / context / options for the
 * selected chip materialize in the reply-context panel below the bar.
 */

.flow-interventions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
}
.flow-interventions:empty { display: none; }

.intervention-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid var(--yellow);
  border-radius: 14px;
  background: rgba(214, 162, 58, 0.12);
  color: var(--fg);
  font: inherit;
  font-size: 11.5px;
  cursor: pointer;
}
.intervention-chip:hover:not(:disabled) { filter: brightness(1.12); }
.intervention-chip.selected {
  box-shadow: 0 0 0 2px rgba(214, 162, 58, 0.55);
}
.intervention-chip.kind-interjection {
  border-color: var(--accent);
  background: rgba(76, 141, 255, 0.12);
}
.intervention-chip.kind-interjection.selected {
  box-shadow: 0 0 0 2px rgba(76, 141, 255, 0.55);
}
.intervention-chip.kind-retry_decision {
  border-color: var(--red);
  background: rgba(224, 86, 75, 0.12);
}
.intervention-chip.kind-retry_decision.selected {
  box-shadow: 0 0 0 2px rgba(224, 86, 75, 0.55);
}
.intervention-chip.kind-discovery_confirm {
  border-color: var(--green);
  background: rgba(76, 175, 106, 0.12);
}
.intervention-chip.kind-discovery_confirm.selected {
  box-shadow: 0 0 0 2px rgba(76, 175, 106, 0.55);
}
/* Lifecycle states for interjection chips: `pending` (interjection has been
 * sent to the daemon and is queued for the running flow to drain) and
 * `consumed` (the running flow has drained it). Driven by ws
 * `interjection_event` phase messages — see applyInterjectionEvent in app.js.
 * Both states are purely visual; click + selection still work normally. */
.intervention-chip.state-pending {
  border-style: dashed;
  background: rgba(76, 141, 255, 0.22);
  animation: chip-pending-pulse 1.6s ease-in-out infinite;
}
.intervention-chip.state-consumed {
  opacity: 0.55;
  text-decoration: line-through;
  background: rgba(76, 175, 106, 0.14);
  border-color: var(--green);
}
@keyframes chip-pending-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(76, 141, 255, 0.25); }
  50%      { box-shadow: 0 0 0 4px rgba(76, 141, 255, 0.10); }
}
.intervention-chip-icon { font-size: 13px; }
.intervention-chip-label {
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 10.5px;
}
.intervention-chip-callid {
  color: var(--fg-dim);
  font-size: 10.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 12ch;
}

/* Interjection lifecycle phases (G4 task 2). Driven by `interjection_event`
 * pushes from the server. `state-pending` is the active "waiting for the
 * flow to consume" state — a subtle dashed border + faint pulse animation;
 * `state-consumed` is a final "the flow has consumed this" state — muted
 * fill so the just-consumed chip lingers visibly for a frame before the
 * snapshot drops it. */
@keyframes interjection-pending-pulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.72; }
}
.intervention-chip.state-pending {
  border-style: dashed;
  animation: interjection-pending-pulse 1.4s ease-in-out infinite;
}
.intervention-chip.state-consumed {
  opacity: 0.55;
  filter: grayscale(0.55);
  text-decoration: line-through;
  text-decoration-color: rgba(0, 0, 0, 0.35);
}

/* -- docked reply box ----------------------------------------------- */

.flow-reply {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 16px 12px;
  background: var(--bg-raised);
  border-top: 1px solid var(--border);
}
.flow-reply-context {
  font-size: 12px;
  color: var(--fg-dim);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.flow-reply-context.active { color: var(--fg); }

.flow-reply-empty,
.flow-reply-hint {
  margin: 0;
  font-size: 11.5px;
  color: var(--fg-dim);
  font-style: italic;
}

.flow-reply-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}
.flow-reply-to {
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 10.5px;
  color: var(--fg-dim);
}
.flow-reply-kind {
  font-weight: 600;
  color: var(--yellow);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 11px;
}
.flow-reply-kind.kind-interjection { color: var(--accent); }
.flow-reply-kind.kind-retry_decision { color: var(--red); }
.flow-reply-kind.kind-discovery_confirm { color: var(--green); }
.flow-reply-callid {
  color: var(--fg-dim);
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Default-collapsed prompt body in the docked reply panel. The trigger toggles
 * the body's `.hidden` (display:none) state; when expanded the body is capped at
 * 30vh and scrolls internally so a very long prompt (e.g. a discovery_confirm
 * embedding the whole refined task description) can never push the textarea /
 * options / Send button out of view. */
.flow-reply-prompt-wrap { display: flex; flex-direction: column; gap: 5px; }
.flow-reply-prompt-toggle {
  align-self: flex-start;
  padding: 2px 9px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--fg-dim);
  font: inherit;
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  cursor: pointer;
}
.flow-reply-prompt-toggle:hover { border-color: var(--fg-dim); color: var(--fg); }
.flow-reply-prompt-wrap.expanded .flow-reply-prompt-toggle {
  color: var(--yellow);
  border-color: var(--yellow);
}

.flow-reply-prompt {
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--fg);
  /* Expanded state: bound the height and scroll internally so the prompt body
   * cannot grow the docked bar without limit. Long single-line content wraps
   * (Long-Content Wrapping convention) rather than producing a horizontal
   * scrollbar. */
  max-height: 30vh;
  overflow-y: auto;
  overflow-x: hidden;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.flow-reply-prompt .md-p { margin: 4px 0; }
.flow-reply-prompt .md-p:first-child { margin-top: 0; }
.flow-reply-prompt .md-p:last-child { margin-bottom: 0; }

.flow-reply-context-block { display: flex; flex-direction: column; gap: 3px; }
.flow-reply-context-label {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--fg-dim);
}
.flow-reply-context-body {
  margin: 0;
  padding: 7px 9px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 5px;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: inherit;
  font-size: 11.5px;
  color: var(--fg-dim);
}

.flow-reply-options {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.flow-reply-option {
  padding: 3px 11px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--accent);
  font-size: 11.5px;
}
.flow-reply-option:hover:not(:disabled) {
  border-color: var(--accent);
  background: var(--bg-card);
}
.flow-reply-option-primary {
  border-color: var(--green);
  color: var(--green);
  font-weight: 600;
}
.flow-reply-option-primary:hover:not(:disabled) {
  border-color: var(--green);
  background: rgba(76, 175, 106, 0.12);
}

.flow-reply-row {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 8px;
}
.flow-reply-row textarea {
  flex: 1 1 220px;
  min-width: 0;
  resize: vertical;
  min-height: 120px;
}
.flow-reply-row textarea:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
#flow-reply-submit { flex-shrink: 0; align-self: flex-end; }

/* Small icon button used at the left end of the reply row (Interject) and
 * symmetric to the Send button on the right. */
.reply-icon-btn {
  flex-shrink: 0;
  align-self: flex-end;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  min-height: 38px;
  padding: 0;
  background: transparent;
  color: var(--fg-dim);
  border: 1px solid var(--border);
  border-radius: 5px;
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
}
.reply-icon-btn:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--fg);
  background: var(--bg-card);
}
.reply-icon-btn.interject.active {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(76, 141, 255, 0.12);
}

@media (max-width: 480px) {
  .flow-reply-row textarea { flex-basis: 100%; }
  #flow-reply-submit { align-self: flex-end; }
}

/* -- collapsed prompt chips ----------------------------------------- */
/*
 * user / system template-style messages render as a one-line clickable chip
 * by default; clicking expands the full record without deleting any content.
 */

.msg-chip-wrap { width: 100%; }
.msg-chip {
  display: block;
  width: 100%;
  text-align: left;
  padding: 5px 10px;
  background: var(--bg-card);
  border: 1px dashed var(--border);
  border-radius: 6px;
  color: var(--fg-dim);
  font: inherit;
  font-size: 11.5px;
  text-transform: lowercase;
  letter-spacing: 0.02em;
  cursor: pointer;
}
.msg-chip:hover { border-color: var(--accent); color: var(--fg); }
.msg-chip-wrap.collapsed .msg-chip-detail { display: none; }
.msg-chip-detail { margin-top: 6px; }

.detail-section { margin-bottom: 16px; }
.detail-section h4 {
  font-size: 12px;
  text-transform: uppercase;
  color: var(--fg-dim);
  margin: 0 0 7px;
}

.step-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
  border-bottom: 1px dotted var(--border);
}
.step-icon { width: 16px; text-align: center; }
.step-icon.completed { color: var(--green); }
.step-icon.failed    { color: var(--red); }
.step-icon.running   { color: var(--accent); }
.step-icon.paused,
.step-icon.pending   { color: var(--fg-dim); }
.step-name { flex: 1; }
.step-dur { color: var(--fg-dim); font-size: 12px; }

.kv { display: flex; gap: 8px; padding: 2px 0; }
.kv .k { color: var(--fg-dim); min-width: 110px; }

/* -- modal ---------------------------------------------------------- */

.modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.55);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 30;
}
.modal-card {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 9px;
  width: min(480px, 92vw);
  max-height: 90vh;
  overflow-y: auto;
}
.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
}
.modal-head h3 { margin: 0; font-size: 14px; }
.modal-body { padding: 14px 16px; display: flex; flex-direction: column; }

.modal-body label {
  font-size: 12px;
  color: var(--fg-dim);
  margin: 10px 0 4px;
}

select, textarea, input {
  background: var(--bg);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 7px 8px;
  font-family: inherit;
  font-size: 13px;
}
textarea { resize: vertical; }
select:focus, textarea:focus { outline: 1px solid var(--accent); }

.modal-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 14px;
}

.form-error {
  color: var(--red);
  font-size: 12px;
  margin: 8px 0 0;
}

.form-hint {
  color: var(--fg-dim);
  font-size: 11.5px;
  font-style: italic;
  margin: 4px 0 0;
}

#nt-project-manual { margin-top: 6px; font-family: ui-monospace, monospace; }
#nt-project-manual.hidden { display: none; }

.modal-body label.checkbox-label {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 7px;
  margin: 12px 0 2px;
  color: var(--fg);
  cursor: pointer;
}
.modal-body label.checkbox-label input {
  width: auto;
  margin: 0;
}

/* -- history view --------------------------------------------------- */

.ghost-btn {
  background: transparent;
  color: var(--fg);
  border: 1px solid var(--border);
}
.ghost-btn:hover:not(:disabled) { border-color: var(--accent); filter: none; }

/* -- issues view ----------------------------------------------------- */

.issues-view {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 25;
  display: flex;
  flex-direction: column;
}
.issues-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
}
.issues-head h3 { margin: 0; font-size: 14px; }

.issues-body {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(260px, 380px) 1fr;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
}
.issues-list-pane, .issues-detail-pane {
  background: var(--bg);
  padding: 14px 16px;
  overflow-y: auto;
}
.issues-list-pane h4, .issues-detail-pane h4 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-dim);
  margin: 0 0 10px;
}
.issues-detail-pane h4 {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 720px) {
  .issues-body { grid-template-columns: 1fr; grid-auto-rows: min-content 1fr; }
}

.issues-list { display: flex; flex-direction: column; gap: 8px; }

/* Issues toolbar: filters + create button */
.issues-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding-bottom: 8px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--border);
}
.issues-toggle-label {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--fg-dim);
  cursor: pointer;
  user-select: none;
}
.issues-toggle-label input { margin: 0; }
.issues-filter-select {
  background: var(--bg);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 4px 6px;
  font-family: inherit;
  font-size: 12px;
}
.issues-toolbar .ghost-btn {
  margin-left: auto;
  padding: 4px 10px;
  font-size: 12px;
}

/* Issue cards */
.issue-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 9px 11px;
  cursor: pointer;
  border-left: 3px solid var(--border);
}
.issue-item:hover { border-color: var(--accent); }
.issue-item.selected { border-color: var(--accent); background: var(--bg-raised); }
.issue-item.issue-source-human { border-left-color: var(--cyan); }
.issue-item.issue-source-system { border-left-color: var(--grey); }

.issue-item-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 6px;
}
.issue-title-text {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
}
.issue-id-label {
  color: var(--fg-dim);
  font-size: 11px;
  flex-shrink: 0;
}
.issue-item-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  color: var(--fg-dim);
  font-size: 11px;
}

/* Issue badges */
.badge-open         { background: rgba(214,162,58,.2); color: var(--yellow); }
.badge-in-progress  { background: rgba(76,141,255,.2); color: var(--accent); }
.badge-resolved     { background: rgba(76,175,106,.2); color: var(--green); }
.badge-wontfix      { background: rgba(106,107,112,.2); color: var(--grey); }
.badge-closed       { background: rgba(106,107,112,.15); color: var(--fg-dim); }

/* Priority badges */
.priority-critical { color: var(--red); font-weight: 600; }
.priority-high     { color: var(--red); }
.priority-medium   { color: var(--yellow); }
.priority-low      { color: var(--fg-dim); }
.priority-none     { color: var(--fg-dim); }

/* Issue detail pane */
.issues-detail {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.issue-detail-header {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
.issue-detail-title {
  flex: 1;
  font-size: 16px;
  font-weight: 600;
  word-break: break-word;
}
.issue-detail-badges {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}
.issue-detail-field {
  display: flex;
  gap: 8px;
  font-size: 13px;
}
.issue-detail-label {
  color: var(--fg-dim);
  flex: 0 0 70px;
}
.issue-detail-value {
  flex: 1;
  word-break: break-word;
}
.issue-detail-desc {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 10px 12px;
  font-size: 13px;
  white-space: pre-wrap;
  word-break: break-word;
}
.issue-detail-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 4px;
}
.issue-detail-actions .ghost-btn {
  padding: 5px 12px;
  font-size: 12px;
}

/* Issue-row "启动 flow" entry: a compact action under the meta line. */
.issue-item-actions {
  display: flex;
  gap: 8px;
  margin-top: 6px;
}
.issue-launch-btn {
  padding: 3px 10px;
  font-size: 11px;
}
.issue-launch-btn.disabled,
.issue-launch-btn:disabled {
  opacity: .45;
  cursor: not-allowed;
}

/* Form row for side-by-side fields */
.form-row {
  display: flex;
  gap: 12px;
}
.form-col {
  flex: 1;
  display: flex;
  flex-direction: column;
}
.form-col label { margin-bottom: 4px; }
.required { color: var(--red); }

/* Small modal variant */
.modal-card-sm { max-width: 420px; }

/* Desktop: hide the issues back button */
@media (min-width: 601px) {
  .issues-back-btn { display: none; }
}

.history-view {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 25;
  display: flex;
  flex-direction: column;
}
.history-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
}
.history-head h3 { margin: 0; font-size: 14px; }

.history-body {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(220px, 320px) 1fr;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
}
.history-list-pane, .history-detail-pane {
  background: var(--bg);
  padding: 14px 16px;
  overflow-y: auto;
}
.history-list-pane h4, .history-detail-pane h4 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-dim);
  margin: 0 0 10px;
}
.history-detail-pane h4 {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 720px) {
  .history-body { grid-template-columns: 1fr; grid-auto-rows: min-content 1fr; }
}

.history-list { display: flex; flex-direction: column; gap: 8px; }

/* Project select dropdown prepended to the history list when sessions span
 * multiple project_roots. A single horizontal row with a label and a native
 * <select>, styled to match the New Task form's Project dropdown. */
.history-project-select-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding-bottom: 6px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--border);
}
.history-project-select-label {
  font-size: 12px;
  color: var(--fg-dim);
  flex: 0 0 auto;
}
.history-project-select {
  flex: 1 1 auto;
  max-width: 100%;
  background: var(--bg);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 5px 8px;
  font-family: inherit;
  font-size: 13px;
}

/* Lightweight "refreshing" bar prepended to a non-empty list while the
 * /api/history round-trip is in flight (the empty-list case reuses .empty). */
.history-refreshing {
  color: var(--fg-dim);
  font-size: 12px;
  padding: 4px 2px;
  margin: 0;
}

.history-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 9px 11px;
  cursor: pointer;
}
.history-item:hover { border-color: var(--accent); }
.history-item.selected { border-color: var(--accent); background: var(--bg-raised); }

.history-item-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 6px;
}
.history-task {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.history-item-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: var(--fg-dim);
  font-size: 11px;
}

.badge-live {
  background: rgba(76,175,106,.2);
  color: var(--green);
}

/* -- history detail (step records) --------------------------------- */

.history-detail { display: flex; flex-direction: column; gap: 14px; }

.history-step {
  border: 1px solid var(--border);
  border-radius: 7px;
  overflow: hidden;
}
.history-step-title {
  margin: 0;
  padding: 7px 11px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--cyan);
}

/* -- viewport-driven sticky floating step header (G5) --------------- */
/*
 * A floating banner that pins to the top of the conversation scroll area and
 * shows the title of whichever step's content currently sits at the viewport
 * top. Shared by the running-flow view (#flow-conversation, its own scroller)
 * and the history view (#history-detail inside the scrolling
 * .history-detail-pane). The outer anchor is a zero-height `position: sticky`
 * box so it never consumes layout height or shifts the conversation; its
 * absolutely-positioned inner button paints the banner over the content top.
 * It is mutually exclusive with the in-stream `.history-step-header` separator
 * rows (JS hides it the instant an original header reaches the top), so the
 * label is never shown twice. Status is carried by the explicit text label, not
 * by colour alone.
 */
.conv-sticky-header {
  position: sticky;
  /* Must equal the negative of the scroll container's padding-top
   * (.flow-conversation / .history-detail-pane both use padding-top: 14px).
   * The sticky `top` threshold is measured against the content box (inner edge
   * of padding); offsetting by -padding-top cancels that padding so the anchor
   * pins to the scroll-viewport edge (outer edge of padding) instead, leaving
   * no gap between the floating header and the top of the scroll region. */
  top: -14px;
  height: 0;
  z-index: 6;
  overflow: visible;
  pointer-events: none;
}
.conv-sticky-header.hidden { display: none; }
.conv-sticky-header__inner {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  width: 100%;
  margin: 0;
  padding: 7px 11px;
  background: var(--bg-raised);
  border: none;
  border-bottom: 1px solid var(--border);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.28);
  font: inherit;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--cyan);
  text-align: left;
  cursor: pointer;
  pointer-events: auto;
}
.conv-sticky-header__inner:hover { background: var(--bg-card, var(--bg-raised)); }
.conv-sticky-header__title {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.history-record {
  padding: 8px 11px;
  border-bottom: 1px dotted var(--border);
  border-left: 3px solid var(--border);
}
.history-record:last-child { border-bottom: none; }
.history-record.role-user      { border-left-color: var(--accent); }
.history-record.role-assistant { border-left-color: var(--green); }
.history-record.role-system    { border-left-color: var(--yellow); }
.history-record.role-other     { border-left-color: var(--grey); }

.history-record-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 5px;
}
.record-role {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--fg-dim);
}
.record-time { color: var(--fg-dim); font-size: 11px; }

.record-body {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: inherit;
  font-size: 12px;
  color: var(--fg);
}

.record-head-right {
  display: flex;
  align-items: center;
  gap: 8px;
}
.record-attempt {
  font-size: 11px;
  color: var(--yellow);
  letter-spacing: 0.04em;
}

/* -- conversation bubbles ------------------------------------------- */
/*
 * Shared by the history view and the running-flow view. Each record is a
 * role-tagged bubble so user / assistant / system are distinguishable at a
 * glance: user aligns right with an accent tint, assistant aligns left with a
 * green tint, system spans the width with a muted yellow tint.
 */

.conv-record { display: flex; flex-direction: column; }

.conv-bubble {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 11px;
  font-size: 12.5px;
  line-height: 1.5;
  max-width: 88%;
  overflow-wrap: anywhere;
}

.conv-record.role-user .conv-bubble {
  align-self: flex-end;
  background: rgba(76, 141, 255, 0.12);
  border-color: rgba(76, 141, 255, 0.4);
}
.conv-record.role-user .history-record-head { flex-direction: row-reverse; }

.conv-record.role-assistant .conv-bubble {
  align-self: flex-start;
  background: rgba(76, 175, 106, 0.10);
  border-color: rgba(76, 175, 106, 0.38);
}

.conv-record.role-system .conv-bubble,
.conv-record.role-other .conv-bubble {
  align-self: stretch;
  max-width: 100%;
  background: rgba(214, 162, 58, 0.08);
  border-color: rgba(214, 162, 58, 0.3);
}
.conv-record.role-other .conv-bubble {
  background: rgba(106, 107, 112, 0.12);
  border-color: var(--border);
}

.conv-plain {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: inherit;
  font-size: 12px;
  color: var(--fg);
}
.conv-empty { color: var(--fg-dim); font-style: italic; }

/* In-progress (stream_progress / partial) bubbles: shown live, line by line,
   while a step is still thinking. Dimmed + a left accent bar so they read as
   transient process output; they are removed once the turn's final result
   arrives. */
.conv-record.conv-partial .conv-bubble {
  opacity: 0.72;
  border-style: dashed;
  border-left: 2px solid rgba(76, 175, 106, 0.55);
}

/* -- markdown elements ---------------------------------------------- */

.conv-bubble .md-p { margin: 6px 0; }
.conv-bubble .md-p:first-child { margin-top: 0; }
.conv-bubble .md-p:last-child { margin-bottom: 0; }

.conv-bubble .md-h {
  margin: 10px 0 5px;
  line-height: 1.3;
  color: var(--fg);
}
.conv-bubble .md-h1 { font-size: 15px; }
.conv-bubble .md-h2 { font-size: 14px; }
.conv-bubble .md-h3 { font-size: 13px; }
.conv-bubble .md-h4,
.conv-bubble .md-h5,
.conv-bubble .md-h6 {
  font-size: 12.5px;
  color: var(--fg-dim);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.conv-bubble .md-list { margin: 6px 0; padding-left: 22px; }
.conv-bubble .md-list li { margin: 2px 0; }

.conv-bubble .md-quote {
  margin: 6px 0;
  padding: 2px 10px;
  border-left: 3px solid var(--border);
  color: var(--fg-dim);
}

.conv-bubble .md-code {
  margin: 6px 0;
  padding: 8px 10px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 5px;
  overflow-x: hidden;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  font-size: 11.5px;
  line-height: 1.45;
}
.conv-bubble .md-code code { font-family: inherit; color: var(--cyan); }

.conv-bubble .md-inline-code {
  padding: 1px 5px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  font-family: inherit;
  font-size: 11.5px;
  color: var(--cyan);
}

.conv-bubble strong { color: var(--fg); font-weight: 600; }
.conv-bubble em { font-style: italic; }

/* -- inline tool-call markers --------------------------------------- */

.tool-marker {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
  margin: 6px 0;
  padding: 5px 9px;
  background: rgba(59, 182, 196, 0.10);
  border: 1px solid rgba(59, 182, 196, 0.4);
  border-left-width: 3px;
  border-radius: 5px;
  font-size: 11.5px;
}
.tool-marker-name {
  flex-shrink: 0;
  color: var(--cyan);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.tool-marker-detail {
  color: var(--fg-dim);
  word-break: break-word;
  overflow-wrap: anywhere;
}
.tool-marker-glyph {
  flex-shrink: 0;
  font-weight: 700;
  font-size: 12px;
}

/* Chip status variants: in-flight (dashed/gray, no glyph), success (solid
 * green with ✓), failure (solid red with ✗). Class names match the
 * `createInFlightChip` / `upgradeChipTo*` state machine. */
.tool-marker.in-flight {
  background: rgba(160, 160, 160, 0.10);
  border-style: dashed;
  border-color: rgba(160, 160, 160, 0.55);
  color: var(--fg-dim);
}
.tool-marker.in-flight .tool-marker-name { color: var(--fg-dim); }
.tool-marker.success {
  background: rgba(82, 196, 102, 0.10);
  border-color: rgba(82, 196, 102, 0.55);
}
.tool-marker.success .tool-marker-name,
.tool-marker.success .tool-marker-glyph { color: #52c466; }
.tool-marker.failure {
  background: rgba(229, 88, 88, 0.10);
  border-color: rgba(229, 88, 88, 0.7);
}
.tool-marker.failure .tool-marker-name,
.tool-marker.failure .tool-marker-glyph { color: #e55858; }

/* Detail panel (collapsible). The toggle button is a chip-head sibling
 * (right-aligned via `margin-left:auto`); the panel itself sits on its own
 * row underneath via `flex-basis:100%`. Failure chips default to
 * `.expanded` so the error is visible without an extra click. */
.tool-marker-details {
  flex-basis: 100%;
  margin-top: 4px;
}
/* Folded state collapses the ENTIRE details wrapper, not just the inner body.
 * In a flex-wrap chip the wrapper keeps `flex-basis:100%`, so hiding only the
 * body left the wrapper claiming a full empty row (its `margin-top:4px` plus
 * the chip's bottom padding showing as a blank band below the collapsed chip).
 * Collapsing the wrapper removes that empty row and stray margin; the expanded
 * state keeps the original flex-basis / margin-top and the body wrapping onto
 * its own row. */
.tool-marker-details.folded { display: none; }
.tool-marker-toggle {
  margin-left: auto;
  flex-shrink: 0;
  background: transparent;
  border: 1px solid rgba(160, 160, 160, 0.4);
  border-radius: 3px;
  color: var(--fg-dim);
  cursor: pointer;
  font-family: inherit;
  font-size: 10.5px;
  padding: 1px 6px;
}
.tool-marker-toggle:hover { color: var(--fg); }
.tool-marker-details-body {
  font-size: 11.5px;
}
.tool-marker-details-fallback {
  background: rgba(0, 0, 0, 0.18);
  color: var(--fg-dim);
  padding: 4px 6px;
  border-radius: 3px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}

/* Diff and line-numbered text content inside a detail panel.
 * Color palette aligns with CLI `display.render_diff` (add=green, del=red,
 * hunk=cyan, ctx=dim). The gutter is dim and right-aligned. */
.tool-marker-diff,
.tool-marker-text,
.tool-marker-text-plain,
.tool-marker-matches,
.tool-marker-bash-stdout,
.tool-marker-bash-stderr {
  font-family: ui-monospace, "JetBrains Mono", Menlo, monospace;
  font-size: 11px;
  background: rgba(0, 0, 0, 0.18);
  padding: 4px 6px;
  border-radius: 3px;
}
.tool-marker-diff-path {
  color: var(--fg-dim);
  font-size: 10.5px;
  font-family: ui-monospace, "JetBrains Mono", Menlo, monospace;
  margin-bottom: 4px;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.diff-line,
.text-line {
  display: flex;
  gap: 8px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.diff-gutter,
.text-gutter {
  flex-shrink: 0;
  width: 3em;
  text-align: right;
  color: var(--fg-dim);
  opacity: 0.55;
  user-select: none;
}
.diff-content,
.text-content {
  flex: 1;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.diff-add { color: #52c466; }
.diff-del { color: #e55858; }
.diff-hunk { color: var(--cyan); }
.diff-ctx { color: var(--fg-dim); }
.diff-truncated {
  color: var(--fg-dim);
  font-style: italic;
  font-size: 10.5px;
  margin-top: 2px;
}
.tool-marker-bash-cmd {
  font-family: ui-monospace, "JetBrains Mono", Menlo, monospace;
  font-size: 11px;
  margin-bottom: 4px;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.tool-marker-bash-label {
  color: var(--cyan);
  margin-right: 6px;
}
.tool-marker-bash-stdout {
  margin: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.tool-marker-bash-stderr-wrap { margin-top: 4px; }
.tool-marker-bash-stderr-label {
  color: #e55858;
  font-size: 10.5px;
  margin-bottom: 2px;
}
.tool-marker-bash-stderr {
  margin: 0;
  color: #e55858;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.tool-marker-match {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.tool-marker-text-pre {
  margin: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.tool-detail-empty {
  color: var(--fg-dim);
  font-style: italic;
  font-size: 10.5px;
}

/* -- long-content folding ------------------------------------------- */

.foldable.folded .fold-full { display: none; }
.foldable.expanded .fold-summary { display: none; }

.fold-summary {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: inherit;
  font-size: 12px;
  color: var(--fg-dim);
  max-height: 9.5em;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(to bottom, #000 65%, transparent);
  mask-image: linear-gradient(to bottom, #000 65%, transparent);
}

.fold-toggle {
  margin-top: 6px;
  padding: 3px 10px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--accent);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}
.fold-toggle:hover {
  border-color: var(--accent);
  background: var(--bg-card);
}

/* -- raw-data toggle ------------------------------------------------- */

.raw-toggle-wrap { margin-top: 6px; }

.raw-toggle {
  padding: 2px 9px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--fg-dim);
  font: inherit;
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  cursor: pointer;
}
.raw-toggle:hover { border-color: var(--fg-dim); color: var(--fg); }
.raw-toggle.active {
  color: var(--yellow);
  border-color: var(--yellow);
}

.raw-json {
  margin: 6px 0 0;
  padding: 8px 10px;
  max-height: 360px;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--bg);
  border: 1px solid var(--border);
  border-left: 3px solid var(--yellow);
  border-radius: 5px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  line-height: 1.45;
  color: var(--fg-dim);
}

.empty { color: var(--fg-dim); font-size: 13px; }
/* History empty-state variants: the loading/connecting hints read as "in
 * progress" (accent), while the confirmed-empty state stays muted so the three
 * are visually distinguishable, not just DOM-distinguishable. */
.empty-loading-refresh,
.empty-loading-connect { color: var(--accent); }
.empty-confirmed { color: var(--fg-dim); }
.hidden { display: none !important; }

/* -- assistant three-layer progressive disclosure ------------------- */
/*
 * Layer 1 is the clean structured result (.assistant-result wrapping a
 * .assistant-structured field block); Layer 2 is the full per-turn process
 * tucked behind the "展开全部" toggle; Layer 3 is the raw NDJSON behind the
 * row-level "查看原始" toggle.
 */
.assistant-result { margin: 0; }
.assistant-narrative { margin: 0 0 8px; }
.assistant-structured { margin: 4px 0 0; }

.process-toggle-wrap { margin-top: 8px; }

.process-toggle {
  padding: 3px 10px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--fg-dim);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}
.process-toggle:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--bg-card);
}

.process-full {
  margin-top: 8px;
  padding-left: 10px;
  border-left: 2px solid var(--border);
}

/*
 * Layer 3 ("查看原始") nests at the end of the Layer-2 "展开全部" area instead of
 * sitting at the row level. A little top spacing plus a hairline separator
 * keeps the raw toggle visually distinct from the process / prefix-suffix
 * content above it. Wrapping rules for the .raw-json body itself are unchanged
 * (Long-Content Wrapping), so a long single-line payload still wraps with no
 * inner horizontal scrollbar.
 */
.process-full .raw-toggle-wrap {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed var(--border);
}

/*
 * No-result assistant turn: the thinking process is shown inline and in full
 * (never folded or contracted), per the message paradigm. The wrapper is a
 * quiet container — it must not introduce its own max-height / overflow so the
 * conversation stays the single vertical scroller and code blocks keep wrapping
 * to the container width.
 */
.assistant-process-inline { margin: 0; }

/* -- user prompt marker (bubble + 展开全部 toggle) ------------------- */
/*
 * When the engine injects TEMPLATE_PREFIX_END / USER_CONTENT_BEGIN /
 * USER_CONTENT_END markers into a user-role prompt, the frontend uses the
 * same three-layer progressive disclosure as the assistant side:
 *   Layer 1 — a default-expanded bubble with ONLY the user's literal input.
 *   Layer 2 — a default-collapsed "展开全部" toggle (`.user-prompt-toggle-wrap`)
 *             revealing the 模板前缀 / 框架后缀 boilerplate.
 *   Layer 3 — the shared "查看原始" raw toggle.
 * The user-content bubble sits on top; the toggle reads as a quiet control
 * directly beneath it. A legacy/empty-content record degrades to the single
 * collapsed `.user-prompt-chip` instead.
 */
.conv-record.user-prompt-marker .user-content-bubble {
  align-self: flex-end;
  background: rgba(76, 141, 255, 0.12);
  border-color: rgba(76, 141, 255, 0.4);
}
.conv-record.user-prompt-marker .user-prompt-toggle-wrap {
  align-self: flex-end;
  max-width: 88%;
  margin-top: 4px;
}
.conv-record.user-prompt-marker .user-prompt-chip {
  align-self: flex-end;
  max-width: 88%;
  margin-bottom: 4px;
}
.conv-record.user-prompt-marker .user-prompt-chip .msg-chip { width: 100%; }

/* -- step event chip (raw step_completed / step_failed) ------------- */

.conv-record.role-step-event {
  align-self: stretch;
  max-width: 100%;
  gap: 6px;
}
.step-event-chip { align-self: stretch; }
.step-event-chip .msg-chip {
  background: rgba(76, 175, 106, 0.10);
  border-color: rgba(76, 175, 106, 0.4);
  border-style: solid;
  color: var(--fg);
}
.step-event-chip.kind-step_failed .msg-chip {
  background: rgba(224, 86, 75, 0.12);
  border-color: rgba(224, 86, 75, 0.5);
}

/* -- per-group DAG status marker (group_status) --------------------- */
/*
 * A lightweight inline status pill tiled into the implement step's time
 * line while the parallel DAG groups run in isolated worktrees. running /
 * completed / failed get distinct colors so the user can tell at a glance
 * which group is in flight versus done versus failed. No fold / raw / chip
 * affordances — it never disturbs the surrounding chat bubbles.
 */
.conv-record.group-status-marker {
  align-self: flex-start;
  max-width: 100%;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 2px 0;
  padding: 3px 10px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--grey);
  border-radius: 6px;
  background: var(--bg-raised);
  font-size: 12px;
  line-height: 1.4;
  color: var(--fg-dim);
}
.group-status-marker .group-status-icon { font-size: 12px; line-height: 1; }
.group-status-marker .group-status-text { white-space: pre-wrap; }
/* The agent/model badge rides inline inside the flex-row marker, so drop the
   stacked-bubble bottom margin and shrink it to sit beside the status text. */
.group-status-marker .agent-badge.group-status-agent {
  margin-bottom: 0;
  padding: 1px 6px;
  font-size: 11px;
}

.group-status-marker.status-queued {
  border-left-color: var(--grey);
  color: var(--fg-dim);
}
.group-status-marker.status-running {
  border-left-color: var(--accent);
  background: rgba(76, 141, 255, 0.10);
  color: var(--fg);
}
.group-status-marker.status-completed {
  border-left-color: var(--green);
  background: rgba(76, 175, 106, 0.10);
  color: var(--fg);
}
.group-status-marker.status-failed {
  border-left-color: var(--red);
  background: rgba(224, 86, 75, 0.12);
  color: var(--fg);
}
.group-status-marker.status-skipped {
  border-left-color: var(--yellow);
  color: var(--fg-dim);
}

/* -- per-step RUNNING status row (step_started) --------------------- */
/*
 * A lightweight "进行中" status line surfaced the instant a step enters
 * RUNNING (including non-LLM steps TEST / COMMIT / SPEC_GATE that emit no
 * conversation records). Like the group-status marker it is affordance-free
 * (no fold / raw / chip) so a step-header rebuild around it, and the later
 * arrival of the step's chat / report records under the same step region,
 * never disturbs it. Status is carried by BOTH an icon and explicit text so
 * it is legible without relying on color alone.
 */
.conv-record.step-status-row {
  align-self: flex-start;
  max-width: 100%;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 2px 0;
  padding: 3px 10px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--grey);
  border-radius: 6px;
  background: var(--bg-raised);
  font-size: 12px;
  line-height: 1.4;
  color: var(--fg-dim);
}
.step-status-row .step-status-icon { font-size: 12px; line-height: 1; }
.step-status-row .step-status-text { white-space: pre-wrap; }
.conv-record.step-status-running {
  border-left-color: var(--accent);
  background: rgba(76, 141, 255, 0.10);
  color: var(--fg);
}
.conv-record.step-status-retrying {
  border-left-color: var(--yellow);
  background: rgba(214, 178, 70, 0.10);
  color: var(--fg);
}
.conv-record.step-status-paused {
  border-left-color: var(--yellow);
  color: var(--fg-dim);
}
.conv-record.step-status-completed {
  border-left-color: var(--green);
  background: rgba(76, 175, 106, 0.10);
  color: var(--fg);
}
.conv-record.step-status-failed {
  border-left-color: var(--red);
  background: rgba(224, 86, 75, 0.12);
  color: var(--fg);
}

/* -- per-step-type visual grouping (G4) ------------------------------ */
/*
 * Every conversation bubble already carries a stable `step-type-<type>` DOM
 * class (added by addConversationRecords in app.js, G2). Here we turn that
 * class into a low-saturation, distinguishable per-step grouping style so a
 * step's boundary is obvious and all records of one step_id read as one
 * region. Two coordinated signals per step:
 *   1. the record's 3px LEFT RAIL is recoloured to the step accent (it
 *      overrides the role-based left stripe ONLY inside the conversation —
 *      role identity is still carried by the bubble's own alignment + tint,
 *      lines below — so the rail now encodes the STEP, the bubble the ROLE);
 *   2. a very faint full-width BACKGROUND LANE in the same hue, kept at
 *      ~0.07 alpha so it tints the lane without lowering text contrast and
 *      survives on mobile where the rail itself is dropped.
 *
 * Scoped to `.history-detail`, the conversation container shared by BOTH the
 * running-flow view (`#flow-conversation.flow-conversation.history-detail`)
 * and the history-detail view (`#history-detail.history-detail`), so the two
 * views group identically. The non-flow history LIST (`.history-item` /
 * top-level `.history-record`) lives OUTSIDE `.history-detail`, so its 3px
 * left identity stripe and padding are untouched.
 *
 * The lightweight status / DAG markers (`.step-status-row`,
 * `.group-status-marker`) keep their own status-coloured styling (they carry
 * a step-type class too), so they are explicitly excluded here.
 */
.history-detail .conv-record.step-type-discovery:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-discovery);
  background: rgba(91, 143, 214, 0.07);
}
.history-detail .conv-record.step-type-analyze:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-analyze);
  background: rgba(63, 169, 191, 0.07);
}
.history-detail .conv-record.step-type-plan:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-plan);
  background: rgba(138, 130, 224, 0.08);
}
.history-detail .conv-record.step-type-confirm:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-confirm);
  background: rgba(111, 134, 201, 0.07);
}
.history-detail .conv-record.step-type-implement:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-implement);
  background: rgba(87, 168, 106, 0.07);
}
.history-detail .conv-record.step-type-test:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-test);
  background: rgba(63, 174, 154, 0.07);
}
.history-detail .conv-record.step-type-self_check:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-self_check);
  background: rgba(200, 154, 70, 0.08);
}
.history-detail .conv-record.step-type-verify_spec:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-verify_spec);
  background: rgba(208, 130, 78, 0.08);
}
.history-detail .conv-record.step-type-update_spec:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-update_spec);
  background: rgba(84, 174, 196, 0.07);
}
.history-detail .conv-record.step-type-spec_gate:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-spec_gate);
  background: rgba(194, 161, 63, 0.08);
}
.history-detail .conv-record.step-type-version_analyze:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-version_analyze);
  background: rgba(168, 127, 196, 0.08);
}
.history-detail .conv-record.step-type-commit:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-commit);
  background: rgba(121, 168, 63, 0.07);
}
.history-detail .conv-record.step-type-summarize:not(.step-status-row):not(.group-status-marker) {
  border-left-color: var(--step-summarize);
  background: rgba(130, 139, 152, 0.09);
}

/* The step-header separator row is the explicit boundary between two step
 * regions. Give it a little extra breathing room above (never before the very
 * first header) so the colour change between lanes is unmistakable; the title
 * keeps its existing reverse-block look. Scoped to the conversation so the
 * history LIST is untouched. */
.history-detail .history-step-header { margin-top: 4px; }
.history-detail .history-step-header:first-child { margin-top: 0; }

/* -- step report card ----------------------------------------------- */
/*
 * Default-expanded report card mirroring the CLI's per-step Rich Panel.
 * Sits inside the .history-step container directly after the raw
 * step_completed chip. No max-height — long reports scroll with the
 * page, not inside a captive viewport (see the running-flow-console
 * spec: per-block height caps are not allowed).
 */
.step-report {
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: 7px;
  background: var(--bg-card);
  margin: 4px 0;
  display: flex;
  flex-direction: column;
}
/* Match each report card's left border to its step's grouping accent so the
 * card reads as the "result/summary" of the same coloured step region. */
.step-report.kind-discovery       { border-left-color: var(--step-discovery); }
.step-report.kind-analyze         { border-left-color: var(--step-analyze); }
.step-report.kind-plan            { border-left-color: var(--step-plan); }
.step-report.kind-confirm         { border-left-color: var(--step-confirm); }
.step-report.kind-implement       { border-left-color: var(--step-implement); }
.step-report.kind-test            { border-left-color: var(--step-test); }
.step-report.kind-self_check      { border-left-color: var(--step-self_check); }
.step-report.kind-verify_spec     { border-left-color: var(--step-verify_spec); }
.step-report.kind-update_spec     { border-left-color: var(--step-update_spec); }
.step-report.kind-spec_gate       { border-left-color: var(--step-spec_gate); }
.step-report.kind-version_analyze { border-left-color: var(--step-version_analyze); }
.step-report.kind-commit          { border-left-color: var(--step-commit); }
.step-report.kind-summarize       { border-left-color: var(--step-summarize); }

.step-report__head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 11px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  user-select: none;
}
.step-report__head:hover { background: var(--bg-card); }
.step-report__toggle {
  background: transparent;
  border: none;
  padding: 0 4px;
  color: var(--fg-dim);
  font-size: 12px;
  cursor: pointer;
}
.step-report__title {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--cyan);
  font-weight: 600;
}

.step-report__body {
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 9px;
  font-size: 12.5px;
  line-height: 1.5;
}

.step-report__status-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  font-size: 12px;
}
.step-report__sep {
  color: var(--fg-dim);
  padding: 0 2px;
}
.step-report__icon { font-weight: 700; }
.step-report__icon.ok   { color: var(--green); }
.step-report__icon.warn { color: var(--yellow); }
.step-report__icon.fail { color: var(--red); }
.step-report__icon.muted { color: var(--fg-dim); }
.step-report__label {
  font-weight: 600;
  text-transform: lowercase;
  letter-spacing: 0.03em;
}
.step-report__label.ok   { color: var(--green); }
.step-report__label.warn { color: var(--yellow); }
.step-report__label.fail { color: var(--red); }
.step-report__label.muted     { color: var(--fg-dim); }
.step-report__label.highlight { color: var(--cyan); }
.step-report__stat { color: var(--fg); }

.step-report__section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.step-report__section-title {
  margin: 0;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--fg-dim);
  font-weight: 600;
}
.step-report__text {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
}

.step-report__list {
  margin: 0;
  padding-left: 18px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.step-report__list li {
  line-height: 1.45;
  overflow-wrap: anywhere;
  word-break: break-word;
  min-width: 0;
}

.step-report__kv { display: flex; flex-direction: column; gap: 2px; }
.step-report__kv-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.step-report__kv-k {
  color: var(--fg-dim);
  min-width: 100px;
  font-weight: 600;
}
.step-report__kv-v {
  color: var(--fg);
  word-break: break-word;
  overflow-wrap: anywhere;
  flex: 1 1 auto;
  min-width: 0;
}
/* Nested dict inside a kv row: indented one level, rendered as another
 * column of kv rows so a `step.outputs` field that is itself a dict
 * still reads as fields rather than a single multi-line JSON literal.
 * `flex-basis:100%` forces a wrap so the nested block starts on its own
 * line below the key, rather than competing for horizontal space with it. */
.step-report__kv-nested {
  flex-basis: 100%;
  margin-left: 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-left: 1px dashed rgba(160, 160, 160, 0.25);
  padding-left: 8px;
}

.step-report__group-id {
  font-weight: 700;
  color: var(--accent);
}
.step-report__group-name {
  color: var(--fg);
}
.step-report__group-meta,
.step-report__muted {
  color: var(--fg-dim);
  font-size: 11.5px;
}
.step-report__warn { color: var(--yellow); }
.step-report__error {
  margin-top: 6px;
  padding: 6px 9px;
  background: rgba(224, 86, 75, 0.12);
  border: 1px solid rgba(224, 86, 75, 0.4);
  border-left: 3px solid var(--red);
  border-radius: 5px;
  color: var(--red);
  font-size: 11.5px;
  white-space: pre-wrap;
  word-break: break-word;
}
.step-report__empty {
  margin: 0;
  color: var(--fg-dim);
  font-style: italic;
  font-size: 11.5px;
}

/* Per-step token-usage footnote (G4): a low-key one-liner at the card's
 * bottom — dim, small, tabular-aligned — so it informs without competing with
 * the structured report above it. */
.step-report__usage {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-top: 2px;
  padding-top: 7px;
  border-top: 1px dashed var(--border);
  color: var(--fg-dim);
  font-size: 11px;
}
.step-report__usage-label {
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.8;
}
.step-report__usage-value {
  font-variant-numeric: tabular-nums;
  word-break: break-word;
}

/* Per-round token-usage footnote (G5): a discreet small-print line at the tail
 * of an interactive assistant bubble (discovery / confirm / …) reporting this
 * round's increment plus the running per-step cumulative. Reuses the dim,
 * tabular-aligned visual of the per-step footnote so it informs without
 * breaking the conversation's continuity. */
.round-usage {
  margin-top: 6px;
  color: var(--fg-dim);
  font-size: 11px;
}
.round-usage__text {
  font-variant-numeric: tabular-nums;
  word-break: break-word;
}

.step-report__files {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.step-report__file-group {
  display: flex;
  flex-direction: column;
}
.step-report__file-dir {
  font-weight: 600;
  color: var(--yellow);
  font-size: 11.5px;
  margin-top: 2px;
}
.step-report__file-row {
  padding-left: 14px;
  color: var(--fg);
  font-size: 11.5px;
  word-break: break-all;
}

.step-report__json {
  margin: 0;
  padding: 6px 8px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
  color: var(--fg-dim);
}

.step-report__markdown { color: var(--fg); }
.step-report__markdown .md-p { margin: 6px 0; }
.step-report__markdown .md-p:first-child { margin-top: 0; }
.step-report__markdown .md-p:last-child  { margin-bottom: 0; }
.step-report__markdown .md-h { color: var(--fg); margin: 8px 0 4px; }
.step-report__markdown .md-list { margin: 6px 0; padding-left: 22px; }
.step-report__markdown .md-code {
  margin: 6px 0;
  padding: 6px 9px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  overflow-x: hidden;
  font-size: 11.5px;
}
.step-report__markdown .md-inline-code {
  padding: 1px 4px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 3px;
  font-family: inherit;
  font-size: 11.5px;
  color: var(--cyan);
}

.step-report__prio {
  font-weight: 600;
  text-transform: uppercase;
  font-size: 10.5px;
  letter-spacing: 0.04em;
}
.step-report__prio.critical { color: var(--red); }
.step-report__prio.high     { color: var(--red); }
.step-report__prio.medium   { color: var(--yellow); }
.step-report__prio.low      { color: var(--fg-dim); }

.step-report__conv-turn {
  display: flex;
  gap: 6px;
  align-items: baseline;
  flex-wrap: wrap;
}

/* -- toast notifications -------------------------------------------- */

.toast-container {
  position: fixed;
  right: 18px;
  bottom: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 50;
  pointer-events: none;
}

.toast {
  min-width: 200px;
  max-width: 360px;
  padding: 9px 13px;
  border-radius: 6px;
  font-size: 13px;
  background: var(--bg-card);
  color: var(--fg);
  border: 1px solid var(--border);
  border-left: 3px solid var(--grey);
  box-shadow: 0 4px 16px rgba(0,0,0,.45);
  opacity: 0;
  transform: translateX(20px);
  transition: opacity .25s ease, transform .25s ease;
  word-break: break-word;
}
.toast.toast-show { opacity: 1; transform: translateX(0); }

.toast-success { border-left-color: var(--green); }
.toast-error   { border-left-color: var(--red); }
.toast-info    { border-left-color: var(--accent); }

/* -- stale-connection banner ---------------------------------------- */

.stale-banner {
  padding: 7px 14px;
  background: rgba(214,162,58,.16);
  color: var(--yellow);
  border-bottom: 1px solid var(--yellow);
  font-size: 12px;
  text-align: center;
  flex-shrink: 0;
}

/* -- login gate (G9) ------------------------------------------------- */

.login-view {
  position: fixed;
  inset: 0;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 40;
}
.login-card {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 9px;
  width: min(380px, 92vw);
  padding: 26px 26px 22px;
}
.login-card h2 { margin: 0 0 4px; font-size: 18px; }
.login-sub { margin: 0 0 18px; color: var(--fg-dim); font-size: 12.5px; }
.login-form { display: flex; flex-direction: column; }
.login-form label {
  font-size: 12px;
  color: var(--fg-dim);
  margin: 10px 0 4px;
}
.login-form button { margin-top: 16px; }
.login-breakglass {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--border);
}
.link-btn {
  background: transparent;
  color: var(--accent);
  border: none;
  padding: 0;
  font-size: 12.5px;
  cursor: pointer;
}
.link-btn:hover { filter: none; text-decoration: underline; }

/* -- top-bar owner label --------------------------------------------- */

.owner-label {
  font-size: 12.5px;
  color: var(--fg);
  padding: 3px 9px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-card);
}

/* -- daemon-key panel (G9) ------------------------------------------- */

.keys-create {
  display: flex;
  gap: 8px;
  margin: 12px 0 6px;
}
.keys-create input { flex: 1; }

.keys-reveal {
  margin: 8px 0;
  padding: 10px 12px;
  border: 1px solid var(--green);
  border-radius: 6px;
  background: rgba(76,175,106,.08);
}
.keys-reveal-note { margin: 0 0 6px; font-size: 12px; color: var(--green); }
.keys-reveal-value {
  display: block;
  font-family: ui-monospace, monospace;
  font-size: 12.5px;
  word-break: break-all;
  color: var(--fg);
}

.keys-list { margin-top: 12px; display: flex; flex-direction: column; gap: 6px; }
.keys-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-card);
}
.keys-row.revoked { opacity: .55; }
.keys-row-label { flex: 1; font-size: 13px; }
.keys-row-status {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 10px;
}
.keys-status-active { color: var(--green); border: 1px solid var(--green); }
.keys-status-revoked { color: var(--grey); border: 1px solid var(--grey); }
.keys-revoke-btn { font-size: 12px; padding: 4px 10px; }

/* -- user-management panel (G3) ------------------------------------- */
/* Reuses the daemon-key row idiom so the two admin modals stay visually
   consistent; only the per-row layout (label + provider + admin badge +
   actions) and the admin/local distinctions are panel-specific. */

.users-create {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin: 12px 0 6px;
}
.users-create input[type="text"],
.users-create input[type="password"] { flex: 1; min-width: 120px; }

.users-list { margin-top: 12px; display: flex; flex-direction: column; gap: 6px; }
.users-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-card);
}
/* The signed-in admin's own row — non-deletable / non-demotable, called out. */
.users-row.is-self { border-color: var(--accent); }
.users-row-main {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-width: 0;
}
.users-row-label { font-size: 13px; color: var(--fg); }
.users-row-provider {
  font-size: 11px;
  color: var(--fg-dim);
  font-family: ui-monospace, monospace;
}
.users-row-admin {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 10px;
}
/* admin vs ordinary user is colour-coded; local-only reset availability is
   conveyed by the presence of the 重置密码 button rather than extra chrome. */
.users-admin-admin { color: var(--accent); border: 1px solid var(--accent); }
.users-admin-user { color: var(--grey); border: 1px solid var(--grey); }
.users-row-self { font-size: 11px; color: var(--accent); }
.users-row-actions { display: flex; gap: 6px; }
.users-row-actions button { font-size: 12px; padding: 4px 10px; }
.users-delete-btn { color: var(--red); border-color: var(--red); }

/* ============================================================================
 * MOBILE PORTRAIT BASELINE  —  @media (max-width: 600px)
 * ============================================================================
 *
 * Breakpoint strategy
 * -------------------
 * This block is the shared base for the mobile-phone-portrait experience. It is
 * an INCREMENTAL OVERLAY: every rule below lives strictly inside this (or the
 * pre-existing 720 / 480) breakpoint, so the desktop layout above is never
 * touched and stays byte-for-byte identical. A wide viewport never matches this
 * query, so none of these rules apply on desktop.
 *
 * Why 600px (not the pre-existing 720px):
 *   - 600px reliably covers mainstream phone portrait widths (<=430 logical px
 *     and their browser-zoom / large-text scaled variants) while staying clear
 *     of the ~768px tablet class, which this pass deliberately does NOT polish.
 *   - The existing 720px block (tablet single-column stacking) is preserved as
 *     is; it still matches phones too, but because this 600px block is authored
 *     LAST in source order it wins on equal specificity for phone-portrait,
 *     letting later mobile groups layer panel-switching / drawers / full-screen
 *     modals on top of this baseline.
 *
 * This baseline group (G1) provides only the foundation that every later mobile
 * group builds on:
 *   1. a global guard against accidental horizontal scrolling, and
 *   2. unified touch-target sizing + iOS-safe form font sizes + a more compact
 *      top bar.
 * Layout re-flows (overflow menu, panel switching, off-canvas drawers,
 * full-screen modals) are added by the later groups within this same breakpoint.
 */
@media (max-width: 600px) {
  /* -- global horizontal-scroll guard -------------------------------- *
   * Phones have no comfortable horizontal scroll affordance, so any element
   * wider than the viewport reads as a layout bug. Clamp the document to the
   * viewport width and stop oversized media / embeds from forcing the page
   * wider than the screen. Per-element long-text wrapping (code blocks, raw
   * JSON, etc.) is handled by the Long-Content Wrapping rules elsewhere; this
   * is the catch-all backstop. */
  html, body {
    overflow-x: hidden;
    max-width: 100%;
  }
  img, video, canvas, svg, iframe {
    max-width: 100%;
    height: auto;
  }

  /* -- unified touch targets ----------------------------------------- *
   * Bump the interactive controls to a finger-friendly minimum height so they
   * are comfortable to tap. ~40px is the practical floor for the chrome here;
   * larger primary actions already exceed it. Chips stay inline-flex and keep
   * vertical centering so the taller box does not misalign their glyph+label. */
  button,
  .icon-btn,
  .intervention-chip,
  .ghost-btn {
    min-height: 40px;
  }
  .intervention-chip {
    display: inline-flex;
    align-items: center;
  }

  /* -- iOS-safe form fields ------------------------------------------ *
   * A font-size below 16px makes mobile Safari auto-zoom the viewport on focus,
   * which then leaves the page scrolled/zoomed. Pin form controls to 16px to
   * suppress that zoom; this only affects the narrow breakpoint. */
  select,
  textarea,
  input {
    font-size: 16px;
  }

  /* -- compact top bar ----------------------------------------------- *
   * Reclaim horizontal room on a narrow screen without hiding any control —
   * tighter padding and gaps only. The functional controls are tucked into the
   * overflow menu below; the version + connection badges stay inline. The
   * top bar is the positioning context for the dropdown. */
  .topbar {
    padding: 8px 12px;
    position: relative;
  }
  .topbar-right {
    gap: 8px;
  }

  /* -- topbar overflow menu (mobile) --------------------------------- *
   * On a narrow screen the auth/admin actions collapse behind the hamburger
   * toggle, preserving every function (nothing is hidden or downgraded — the
   * controls are only relocated into a dropdown). The toggle is shown here and
   * sized as a comfortable touch target; the G1 baseline already pins buttons
   * to a 40px min-height. */
  .nav-menu-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 40px;
    padding: 6px 10px;
    font-size: 20px;
    line-height: 1;
  }

  /* Collapsed by default: the menu is removed from flow so it occupies no
   * space when shut. When `.open`, it drops down as an absolutely-positioned
   * panel anchored to the top bar's bottom-right, stacking its controls
   * vertically as full-width tap targets. */
  .nav-menu {
    display: none;
  }
  .nav-menu.open {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
    position: absolute;
    top: 100%;
    right: 8px;
    margin-top: 6px;
    padding: 10px;
    min-width: 180px;
    max-width: calc(100vw - 16px);
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: 9px;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
    z-index: 28;
  }
  /* Each control fills the dropdown width and centers its label; the owner
   * label reads as a non-interactive heading row. */
  .nav-menu.open > button {
    width: 100%;
    justify-content: center;
    text-align: center;
  }
  .nav-menu.open > .owner-label {
    width: 100%;
    text-align: center;
    padding: 4px 0;
  }

  /* -- main list: single-view panel switch (Machines <-> Flows) ------ *
   * The desktop two-column grid, merely stacked (the 720px rule), would push
   * the Flows list below the entire machine list and off the first screen. On
   * a phone we instead show exactly one panel at a time: both panes are placed
   * in the same single grid cell and toggled by display. The machine list is
   * the default; once a machine is picked, `#main-layout` gains `active-flows`
   * (set from JS) to reveal the Flows pane, and the back button returns to the
   * list. Desktop never matches this breakpoint, so its grid is untouched. */
  .layout {
    grid-template-columns: 1fr;
    grid-template-rows: 1fr;
  }
  .machines-pane,
  .flows-pane {
    grid-column: 1;
    grid-row: 1;
  }
  /* Default: machines visible, flows hidden. */
  .flows-pane { display: none; }
  /* active-flows: flows visible, machines hidden. */
  .layout.active-flows .machines-pane { display: none; }
  .layout.active-flows .flows-pane { display: block; }

  /* The back button leads from the Flows panel back to the machine list; it is
   * a comfortable touch target (the G1 baseline pins buttons to 40px min). */
  .flows-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0 0 10px;
    padding: 6px 12px;
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--fg);
    font-size: 14px;
  }

  /* -- History view: single-view panel switch (Sessions <-> Detail) -------- *
   * Isomorphic to the main-list switch above. The desktop two-column grid,
   * merely stacked (the existing 720px rule), would push the session detail
   * below the whole session list and off the first screen. On a phone we show
   * exactly one panel at a time: both panes share the same single grid cell and
   * are toggled by display. The session list is the default; once a session is
   * picked, `#history-view` gains `active-detail` (set from JS) to reveal the
   * detail pane, and the back button returns to the list. Desktop never matches
   * this breakpoint, so its History grid is untouched. */
  .history-body {
    grid-template-columns: 1fr;
    grid-template-rows: 1fr;
  }
  .history-list-pane,
  .history-detail-pane {
    grid-column: 1;
    grid-row: 1;
  }
  /* Default: session list visible, detail hidden. */
  .history-detail-pane { display: none; }
  /* active-detail: detail visible, list hidden. */
  .history-view.active-detail .history-list-pane { display: none; }
  .history-view.active-detail .history-detail-pane { display: block; }

  /* The back button leads from the session detail back to the session list; a
   * comfortable touch target (the G1 baseline pins buttons to 40px min). */
  .history-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0 0 10px;
    padding: 6px 12px;
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--fg);
    font-size: 14px;
  }

  /* -- History view: mobile overflow hardening -------------------------------- *
   * The History list+detail two-column grid collapses to a single-view panel
   * switch above, but the panes and their inner content can still overflow
   * horizontally on a narrow viewport. Two layers fix that:
   *
   * (a) Container shrink — every flex/grid child that could blow out its parent
   *     gets `min-width: 0` so flex-shrink / grid sizing can actually compress it
   *     below its content's intrinsic width. The two panes additionally carry
   *     `overflow-x: hidden` as a backstop: even if an inner element somehow
   *     exceeds the pane width, the pane clips it rather than introducing a
   *     horizontal scrollbar. (Desktop keeps its natural `overflow-y: auto` on
   *     the panes; the hidden x is mobile-only.)
   *
   * (b) Long-content wrapping — text nodes that naturally produce unbreakable
   *     long runs (project-select option text, session meta spans, step titles,
   *     message chips) get `overflow-wrap: anywhere` + `word-break: break-word`
   *     so they wrap character-by-character instead of pushing the container
   *     wider. The `<select>` flex-basis is zeroed (`flex: 1 1 0`) for the same
   *     reason the `.tool-marker-detail` fix zeroes it: with `flex-basis: auto`
   *     the select's min-content width (its longest `<option>`) pins the flex
   *     line wider than the column before flex-shrink applies. Zeroing the basis
   *     lets the select shrink and the ellipsis/wrapping take over.
   *
   * Every selector carries the `#history-view` prefix so it is unique to the
   * History view and never affects the flow-view or any other surface sharing
   * the same class names. */

  /* (a) Container shrink */
  #history-view .history-body {
    max-width: 100%;
  }
  #history-view .history-list-pane,
  #history-view .history-detail-pane {
    min-width: 0;
    max-width: 100%;
    overflow-x: hidden;
  }
  #history-view .history-detail,
  #history-view .history-step {
    min-width: 0;
    max-width: 100%;
  }

  /* (b) Long-content wrapping */
  #history-view .history-project-select-row {
    flex-wrap: wrap;
    min-width: 0;
  }
  /* flex-basis 0 (same root cause as .tool-marker-detail): the native <select>
   * min-content width is its longest <option>, which with flex-basis auto pins
   * the row wider than the viewport. Zeroing the basis lets the select shrink. */
  #history-view .history-project-select {
    flex: 1 1 0;
    min-width: 0;
    max-width: 100%;
  }
  #history-view .history-item-meta {
    flex-wrap: wrap;
  }
  #history-view .history-item-meta > span {
    min-width: 0;
    overflow-wrap: anywhere;
    word-break: break-word;
  }
  #history-view .history-step-title {
    overflow-wrap: anywhere;
    word-break: break-word;
  }
  #history-view .msg-chip {
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  /* -- running console (#flow-view): off-canvas sidebar drawer (G4) -------- *
   * The desktop two-column grid (sidebar | conversation) would, when merely
   * stacked, push the conversation below the whole Overview/Steps/Machine
   * sidebar and off the first screen. On a phone we instead let the
   * conversation own the full main column and turn the sidebar into a drawer
   * that slides in over the conversation when the head toggle is tapped, with
   * a tap-to-close backdrop. Desktop never matches this breakpoint, so its
   * grid is untouched. */

  /* The head toggle (☰) becomes a visible touch target. The G1 baseline pins
   * buttons to a 40px min-height; .icon-btn already centers its glyph. */
  .flow-sidebar-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  /* Collapse the body to a single cell so the conversation/main column fills
   * the whole width (overriding the 720px stacked grid). The sidebar is lifted
   * out of flow below, so the lone remaining grid item is the main column. */
  .flow-view-body {
    grid-template-columns: 1fr;
    grid-template-rows: 1fr;
  }
  .flow-main {
    grid-column: 1;
    grid-row: 1;
    min-width: 0;
  }

  /* The sidebar becomes a fixed off-canvas drawer: parked just off the left
   * edge by default, slid in when `#flow-view.sidebar-open`. It keeps its own
   * vertical scroll for long Overview/Steps content. */
  .flow-sidebar {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: 84%;
    max-width: 320px;
    z-index: 30;
    transform: translateX(-100%);
    transition: transform 0.22s ease;
    box-shadow: 2px 0 18px rgba(0, 0, 0, 0.5);
    -webkit-overflow-scrolling: touch;
  }
  .flow-view.sidebar-open .flow-sidebar {
    transform: translateX(0);
  }

  /* The backdrop dims the conversation behind the open drawer and is the
   * tap-to-close target. Hidden until the drawer is open. */
  .flow-sidebar-backdrop {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 29;
    background: rgba(0, 0, 0, 0.5);
  }
  .flow-view.sidebar-open .flow-sidebar-backdrop {
    display: block;
  }

  /* -- running console: docked reply area touch optimisation (G4) --------- *
   * Enlarge the reply controls and stack them vertically so a thumb can
   * comfortably pick a chip, draft a multi-line reply, and Interject / Send.
   * The textarea stays always-editable and the Send gating is untouched —
   * these are purely layout/sizing rules. */
  .flow-reply {
    /* Respect the home-bar safe area on notched phones so Send is reachable. */
    padding: 10px 12px calc(12px + env(safe-area-inset-bottom, 0px));
  }

  /* Intervention chips: roomier tap targets that wrap freely. */
  .flow-interventions {
    gap: 8px;
  }
  .intervention-chip {
    padding: 8px 12px;
    font-size: 13px;
  }

  /* Option buttons (confirm / retry choices) get finger-friendly padding. */
  .flow-reply-option {
    padding: 8px 14px;
    font-size: 13px;
  }

  /* Reply row: textarea on its own full-width line, then the Interject and
   * Send buttons share the row below it as tall, easy-to-hit controls. */
  .flow-reply-row {
    gap: 8px;
  }
  .flow-reply-row textarea {
    order: 1;
    flex: 1 1 100%;
    /* WeChat-style auto-grow (G3): start at a single-line minimum and let
     * `autoGrowReplyTextarea` in app.js size it to the content up to ~35vh,
     * then scroll internally. The desktop 6-row default + manual
     * `resize: vertical` are dropped on the phone (the height is JS-driven and
     * the manual handle is removed), so the old fixed 104px floor is gone.
     * Desktop never matches this breakpoint, so its textarea is intact. */
    min-height: 40px;
    max-height: 35vh;
    overflow-y: auto;
    resize: none;
  }
  .reply-icon-btn {
    order: 2;
    align-self: stretch;
    width: auto;
    min-width: 52px;
    min-height: 44px;
  }
  #flow-reply-submit {
    order: 3;
    flex: 1 1 auto;
    align-self: stretch;
    min-height: 44px;
  }

  /* -- chat conversation: reclaim horizontal whitespace (G1) -------------- *
   * Each flow chat record is a `.history-record.conv-record.role-*` node, so it
   * inherits the history-LIST view's row identity markers: a 3px colored left
   * bar (role-user blue / role-assistant green) plus 11px side padding. In the
   * bubble chat view the bubble already carries its own colored border + tint,
   * so that bar is redundant; combined with the outer `.flow-conversation` 16px
   * padding and the record's own 11px it eats ~30px on the left, while the 88%
   * bubble cap leaves a big right-side gap. On a phone we strip the bar +
   * record padding, narrow the outer padding to 8px, and let the bubble reach
   * (near) full width — identity stays legible from the bubble's own colored
   * border + tint alone. All rules are scoped under `.flow-conversation`, so
   * the history-LIST view's `.history-record` bar/padding are untouched. */
  .flow-conversation {
    padding: 14px 8px;
  }
  .flow-conversation .history-record {
    border-left: none;
    padding-left: 0;
    padding-right: 0;
  }
  /* Bubbles go (near) full width and stop offsetting left/right; the bubble's
   * own `padding: 8px 11px` + colored border / tint are kept for breathing room
   * and identity. */
  .flow-conversation .conv-record.role-user .conv-bubble,
  .flow-conversation .conv-record.role-assistant .conv-bubble {
    max-width: 100%;
    align-self: stretch;
  }

  /* -- tool-call chip: compress the summary to one line (G2) -------------- *
   * Desktop lets the chip head wrap; on a narrow screen the name + detail then
   * spill onto multiple lines. Root cause: the chip head is `flex-wrap: wrap`,
   * and the previous `flex: 1 1 auto` left the detail with a flex-basis of
   * `auto` — i.e. its hypothetical main size was its full content width. When
   * the content was long that hypothetical size overflowed the line, so the
   * flex line-collection step wrapped the detail onto a second row BEFORE
   * flex-shrink ever applied, and the nowrap/ellipsis never engaged. Pinning
   * `flex-basis: 0` (via `flex: 1 1 0`) drops the detail's hypothetical main
   * size to 0 (clamped by `min-width: 0`), so it never forces a wrap; it then
   * grows to fill the remaining width on the single head line and
   * single-line-ellipsis-truncates an over-long detail. The fixed-size head
   * children (`.tool-marker-name` / `.tool-marker-glyph` / `.tool-marker-toggle`)
   * already carry `flex-shrink: 0`, so they keep their natural width and the
   * grown detail pushes the toggle to the row end. The expandable details panel
   * (`.tool-marker-details`, `flex-basis: 100%`) still wraps onto its own row
   * and shows the full diff / bash / text content when expanded — its
   * `flex-wrap: wrap` parent is left intact so the panel keeps dropping to a new
   * line, and its folded state stays `display: none`. */
  .flow-conversation .tool-marker-detail {
    flex: 1 1 0;
    min-width: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  /* -- tool-call chip: un-stretch the "details" toggle button (problem 1) - *
   * `.tool-marker-toggle` is a <button>, so the G1 baseline `button { min-height:
   * 40px }` touch-target rule above grabs this tiny secondary "details" expand
   * affordance and inflates it to 40px, which in turn stretches the whole
   * `.tool-marker` chip row far taller than its text. This override DELIBERATELY
   * relaxes the 40px touch target for THIS one minor toggle so the button hugs
   * its text and the card returns to its natural height. It is scoped precisely
   * to `.flow-conversation .tool-marker-toggle`, so every other control caught by
   * `button { min-height: 40px }` (icon-btn / intervention-chip / ghost-btn /
   * reply option buttons …) keeps its full touch target. Only the vertical size
   * is collapsed (min-height + line-height + zeroed vertical padding); the
   * horizontal padding (6px) and font-size (10.5px) are inherited from the
   * desktop `.tool-marker-toggle` rule unchanged. Desktop never matches this
   * breakpoint, so the desktop toggle is byte-for-byte intact.
   *
   * REAL ROOT CAUSE (verified by headless render): on the actual mobile WebKit
   * browser the toggle is STILL tall after the min-height/line-height/padding
   * relaxation above, because a `<button>` defaults to `appearance: auto` — a
   * NATIVE form control whose intrinsic vertical metrics (the platform button's
   * own min size + internal vertical padding) are NOT removable by `min-height`
   * / `padding` / `line-height` alone. Desktop Chrome happens not to impose that
   * native floor, so the earlier fix "looked like it worked" on desktop but
   * showed no change on the phone — matching the reported "改了没区别". The fix
   * is `-webkit-appearance: none; appearance: none;`, which strips the native
   * control so the button becomes a plain box that finally honors the compacting
   * declarations on mobile WebKit too. It is a no-op on desktop Chrome (already
   * compact) and is scoped inside this breakpoint, so desktop stays byte-intact. */
  .flow-conversation .tool-marker-toggle {
    -webkit-appearance: none;
    appearance: none;
    min-height: auto;
    line-height: 1;
    padding-top: 3px;
    padding-bottom: 3px;
  }

  /* The chip head aligns its children on the text BASELINE
   * (`.tool-marker { align-items: baseline }`). Once the toggle is compacted to
   * its text height, baseline math can still let the row's height be driven by
   * the tallest item's ascent+descent. Re-centering the head line on the cross
   * axis (scoped to the mobile breakpoint only) guarantees the now-flattened
   * toggle button can never re-inflate the row via baseline alignment, so the
   * folded `.tool-marker` card stays at its natural compact height. The desktop
   * rule keeps `align-items: baseline` untouched. The expandable details panel
   * (`flex-basis: 100%`) still wraps to its own row. */
  .flow-conversation .tool-marker {
    align-items: center;
    /* Reassign the card's top/bottom padding onto the toggle button above:
     * the toggle gains 3px top+bottom padding so its text no longer hugs its
     * own border, and the card sheds an equal amount of vertical padding
     * (desktop 5px → 2px top/bottom) so the folded chip's total height stays
     * essentially unchanged. Left/right padding (9px) is inherited from the
     * desktop rule untouched. */
    padding-top: 2px;
    padding-bottom: 2px;
  }

  /* -- per-step grouping: contain on mobile, status text wraps (G4) ------- *
   * The per-step grouping lanes (faint background + left rail, defined at the
   * top level on `.history-detail .conv-record.step-type-*`) and the
   * lightweight "进行中" / status rows must never widen the conversation past
   * the phone viewport. These are CSS-only containment + wrapping guards,
   * scoped to `#flow-view` / `#history-view` so desktop and every other view
   * stay byte-for-byte unchanged. Following the Mobile Horizontal-Overflow
   * contract, no horizontal-scroll escape hatch is introduced: content WRAPS.
   *
   * `min-width: 0` is the flex/grid blowout guard (a wide tinted lane child can
   * otherwise pin the column wider than the viewport); `max-width: 100%` caps
   * the lane to the column. */
  #flow-view .flow-conversation .conv-record,
  #history-view .history-detail .conv-record {
    min-width: 0;
    max-width: 100%;
  }
  /* The status row is an inline-flex pill; let it wrap and break a long step
   * label rather than forcing a horizontal scroll. */
  #flow-view .step-status-row,
  #history-view .step-status-row {
    flex-wrap: wrap;
    min-width: 0;
    max-width: 100%;
  }
  #flow-view .step-status-row .step-status-text,
  #history-view .step-status-row .step-status-text {
    min-width: 0;
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  /* -- idle reply placeholder: shrink so it fits one line (problem 2) ------ *
   * The idle "可先草拟回复,或点 ✎ 插话…" placeholder rides the 16px form-field
   * floor (the iOS-zoom guard above), which on a phone wraps to two lines in the
   * default single-line (collapsed) textarea. Shrink ONLY the placeholder so the
   * hint fits one line; the textarea's own 16px input text is left untouched, so
   * real typing keeps the iOS-zoom guard and the normal input size. Paired with
   * the shortened placeholder string (app.js). Desktop is unaffected. */
  #flow-reply-input::placeholder {
    font-size: 13px;
  }

  /* -- docked reply meta: tile head + prompt toggle on one row (G2) ------- *
   * Desktop stacks the reply-context children vertically (the TO/KIND head
   * row, then the "▸ 展开消息详情" prompt toggle row, then the options row),
   * wasting the right-side whitespace and eating vertical room. On a phone lay
   * the active context out as a wrapping row so the head and the prompt toggle
   * share one line; the expandable prompt body and the options buttons drop to
   * their own full-width rows below. The expanded `.flow-reply-prompt` keeps its
   * `max-height: 30vh` internal scroll (defined at the top level). */
  #flow-view .flow-reply-context.active {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: baseline;
    column-gap: 10px;
  }
  #flow-view .flow-reply-context.active .flow-reply-head {
    flex: 0 0 auto;
  }
  #flow-view .flow-reply-context.active .flow-reply-prompt-wrap {
    flex: 1 1 auto;
    min-width: 0;
  }
  #flow-view .flow-reply-context.active .flow-reply-options {
    flex-basis: 100%;
  }

  /* -- docked reply: share the chip bar with the reply-head row (problem 2) *
   * Desktop stacks the docked reply area as a column: the `#flow-interventions`
   * chip bar on its own row, the `.flow-reply-context` (whose first line is the
   * "回复中 · <kind>" `.flow-reply-head`) below it, then the input row. On a
   * phone a single `call` chip then claims a full, tall, mostly-empty row above
   * a head that says almost the same thing — wasted vertical space.
   *
   * Flip the docked `.flow-reply` form itself to a wrapping row so the chip bar
   * and the reply-context sit side by side on the first visual line (the chip
   * keeps its natural width, the context takes the rest), while the input row
   * (`.flow-reply-row`) is forced onto its own full-width line below. The
   * `.flow-reply-context.active` is itself laid out as a wrapping row (rule
   * above), so its `.flow-reply-head` lands at the top-left of that remaining
   * width — i.e. on the same visual line as the chip — reclaiming the chip's
   * former dedicated row. The chip-selection / Send gating semantics are
   * untouched (these are pure layout rules). Scoped to the 600px breakpoint, so
   * the desktop column stack is byte-for-byte intact. */
  #flow-view .flow-reply {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: flex-start;
    column-gap: 8px;
  }
  #flow-view .flow-reply .flow-interventions {
    flex: 0 0 auto;
    max-width: 60%;
    /* The G1 baseline pins chips to a 40px touch target; keep that but let the
     * chip hug its content so it does not bloat the shared row. */
    margin: 0;
  }
  #flow-view .flow-reply .flow-reply-context {
    flex: 1 1 0;
    min-width: 0;
  }
  #flow-view .flow-reply .flow-reply-row {
    flex: 0 0 100%;
  }

  /* -- discovery_confirm dock: tidy the scattered mobile layout (problem 3) *
   * The discovery confirmation dock crowds four mismatched blocks together: a
   * big green "✓ 确认任务描述" chip, a near-duplicate "回复中 · 确认任务描述" head,
   * a boxed uppercase "▸ 展开消息详情" toggle stranded alone on its own row, and
   * the "确认并继续 (输入 1)" button — unaligned, uneven in size, and repeating the
   * same label. Every rule below is scoped to `kind-discovery_confirm` inside the
   * 600px breakpoint, so other kinds and the entire desktop panel are untouched.
   *
   * (a) De-dup: the chip already reads "✓ 确认任务描述", so hide the head that
   *     repeats it. After this, the context's first visible child is the
   *     prompt-toggle, which then tiles next to the chip on the shared row. */
  #flow-view .flow-reply-context.kind-discovery_confirm .flow-reply-head {
    display: none;
  }

  /* (b) Lightweight expand entry: drop the boxed/uppercase look of the
   *     "展开消息详情" toggle and render it as a plain text link whose size matches
   *     the surrounding secondary text, so it stops standing out and stops eating
   *     a whole empty row. It is given the chip's 40px height + centering so it
   *     aligns with the chip on the shared row (see (c)). */
  #flow-view .flow-reply-context.kind-discovery_confirm .flow-reply-prompt-toggle {
    display: inline-flex;
    align-items: center;
    min-height: 40px;
    align-self: center;
    border: none;
    padding: 0;
    text-transform: none;
    letter-spacing: 0;
    font-size: 12px;
    color: var(--accent);
  }
  #flow-view .flow-reply-context.kind-discovery_confirm .flow-reply-prompt-toggle:hover {
    border: none;
    color: var(--accent);
    text-decoration: underline;
  }
  /* Keep the expanded-state toggle the same lightweight link (override the
   * desktop expanded rule that re-adds a yellow border). */
  #flow-view .flow-reply-context.kind-discovery_confirm .flow-reply-prompt-wrap.expanded .flow-reply-prompt-toggle {
    border: none;
    color: var(--accent);
  }

  /* (c) Alignment + hierarchy: with the head gone, the chip and the expand link
   *     share the first row (the chip via `.flow-reply` flex-wrap, the link as
   *     the context's first child). Center them vertically against each other and
   *     keep the prompt-toggle row tight; the confirm button drops to its own
   *     full-width row below as the clear primary action. */
  #flow-view .flow-reply-context.kind-discovery_confirm.active {
    align-items: center;
    row-gap: 8px;
  }
  #flow-view .flow-reply-context.kind-discovery_confirm .flow-reply-prompt-wrap {
    gap: 0;
  }
  /* Confirm button: full-width, emphasized primary CTA so it reads as the
   * panel's main action rather than one more same-size chip. */
  #flow-view .flow-reply-context.kind-discovery_confirm .flow-reply-options {
    flex-basis: 100%;
  }
  #flow-view .flow-reply-context.kind-discovery_confirm .flow-reply-option-primary {
    flex: 1 1 auto;
    text-align: center;
    justify-content: center;
  }

  /* -- modals: near full-screen on phone portrait (G6) -------------------- *
   * Desktop centers a 480px card (`width: min(480px, 92vw); max-height: 90vh`),
   * which on a phone leaves cramped side gutters and a short inner scroll area.
   * Here every modal (New Task / Daemon Keys / 用户管理) fills the viewport:
   * the overlay stops centering, the card spans the full width/height with
   * squared corners and no margin, and the body becomes the sole scroller so
   * long forms and lists stay fully reachable. Desktop never matches this
   * breakpoint, so the centered-card look is byte-for-byte intact. */
  .modal {
    align-items: stretch;
    justify-content: stretch;
  }
  .modal-card {
    width: 100vw;
    max-width: 100vw;
    /* 100dvh tracks the dynamic viewport (mobile URL bar) so the card never
     * overshoots; the 100vh line is the fallback for browsers without dvh. */
    height: 100vh;
    height: 100dvh;
    max-height: 100vh;
    max-height: 100dvh;
    border-radius: 0;
    border: none;
    /* Card is the flex frame: fixed head + scrolling body. Overflow moves from
     * the card (desktop) onto the body below, so the head stays pinned. */
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }
  .modal-head {
    flex: 0 0 auto;
  }
  .modal-body {
    flex: 1 1 auto;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    /* Keep the last control clear of the home-bar safe area on notched phones. */
    padding-bottom: calc(14px + env(safe-area-inset-bottom, 0px));
  }

  /* -- in-modal create forms: vertical stacking (G6) --------------------- *
   * The daemon-key and user create forms lay their input(s) + button out in a
   * horizontal row on desktop; on a phone that squeezes each field too narrow
   * to tap. Stack them vertically as full-width controls instead. The G1
   * baseline already pins inputs to 16px and buttons to a 40px touch height. */
  .keys-create,
  .users-create {
    flex-direction: column;
    align-items: stretch;
  }
  .keys-create input,
  .users-create input[type="text"],
  .users-create input[type="password"] {
    flex: none;
    width: 100%;
    min-width: 0;
  }
  .keys-create button,
  .users-create button {
    width: 100%;
  }

  /* -- per-user rows: wrap actions onto their own line (G6) -------------- *
   * A users-row packs an identity block plus delete / reset / admin-toggle
   * actions. On a phone those buttons would crush against the label; let the
   * row wrap so the action cluster drops to a full-width line and each button
   * grows to a comfortable touch target. keys-row wraps defensively too. */
  .users-row,
  .keys-row {
    flex-wrap: wrap;
  }
  .users-row-actions {
    flex-wrap: wrap;
    width: 100%;
    gap: 8px;
  }
  .users-row-actions button {
    flex: 1 1 auto;
    min-height: 40px;
    font-size: 13px;
    padding: 8px 12px;
  }

  /* -- Issues view: single-view panel switch (List <-> Detail) ----------- *
   * Isomorphic to the History view switch. On a phone we show exactly one
   * pane at a time; the list is the default, and selecting an issue reveals
   * the detail pane (with a back button to return). */
  .issues-body {
    grid-template-columns: 1fr;
    grid-template-rows: 1fr;
  }
  .issues-list-pane,
  .issues-detail-pane {
    grid-column: 1;
    grid-row: 1;
  }
  .issues-detail-pane { display: none; }
  .issues-view.active-detail .issues-list-pane { display: none; }
  .issues-view.active-detail .issues-detail-pane { display: block; }

  .issues-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0 0 10px;
    padding: 6px 12px;
    background: var(--bg-raised);
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--fg);
    font-size: 14px;
  }

  /* Issues container shrink */
  #issues-view .issues-body { max-width: 100%; }
  #issues-view .issues-list-pane,
  #issues-view .issues-detail-pane {
    min-width: 0;
    max-width: 100%;
    overflow-x: hidden;
  }
  #issues-view .issues-detail { min-width: 0; max-width: 100%; }

  /* Issues long-content wrapping */
  #issues-view .issues-toolbar { flex-wrap: wrap; min-width: 0; }
  #issues-view .issues-filter-select { flex: 1 1 0; min-width: 0; max-width: 100%; }
  #issues-view .issue-item-meta { flex-wrap: wrap; }
  #issues-view .issue-item-meta > span,
  #issues-view .issue-title-text {
    min-width: 0;
    overflow-wrap: anywhere;
    word-break: break-word;
  }

  /* -- login gate + break-glass: narrow-screen margins/sizing (G6) ------- *
   * Let the login card use the full phone width (minus a small gutter) and
   * top-align it so the on-screen keyboard does not shove a vertically centered
   * card off-screen. The G1 baseline already pins the form fields to 16px. */
  .login-view {
    align-items: flex-start;
    padding: 24px 16px;
    overflow-y: auto;
  }
  .login-card {
    width: 100%;
    max-width: 100%;
    padding: 22px 18px 18px;
  }
  .login-form button,
  .login-breakglass button[type="submit"] {
    width: 100%;
  }
}

