    partialRecord("r1-p2", 2, "s1", "discovery", 0),   // idx 1 — round 1, folds
    finalRecord("r1-final", 3, "s1", "discovery", 0),  // idx 2 — round 1 terminal
    partialRecord("r2-p1", 4, "s1", "discovery", 0),   // idx 3 — round 2, stays live
