  const analyzeFields = app.STEP_RESULT_FIELDS && app.STEP_RESULT_FIELDS.analyze;
  assert.ok(Array.isArray(analyzeFields) && analyzeFields.length,
    "STEP_RESULT_FIELDS.analyze is non-empty");
