/* SE3 Control Plane — dark theme, CLI-flavoured. */

:root {
  --bg: #1a1b1e;
  --bg-raised: #232428;
  --bg-card: #2a2b30;
  --border: #3a3b40;
  --fg: #d8d9dd;
  --fg-dim: #8a8b90;
  --accent: #4c8dff;
  --green: #4caf6a;
  --yellow: #d6a23a;
  --red: #e0564b;
  --cyan: #3bb6c4;
  --grey: #6a6b70;

  /* Per-step-type grouping accents (G4). A stable, low-saturation, mutually
   * distinguishable hue per StepType, used both for each step region's left
   * rail / faint background lane in the conversation and for the matching
   * step-report card border, so the same step always reads in the same colour
   * across running-flow and history views. Deliberately desaturated so the
   * faint background tints never drop text contrast below AA on the dark
   * surface — status is ALSO carried by text + icon (see step-status rows), so
   * colour is never the sole signal. Adjacent flow steps
   * (discovery→analyze→plan→implement→test→self_check→verify_spec→update_spec
   * →spec_gate→version_analyze→commit→summarize) carry visibly different hues. */
  --step-discovery: #5b8fd6;
  --step-analyze: #3fa9bf;
  --step-plan: #8a82e0;
  --step-confirm: #6f86c9;
  --step-implement: #57a86a;
  --step-test: #3fae9a;
  --step-self_check: #c89a46;
  --step-verify_spec: #d0824e;
  --step-update_spec: #54aec4;
  --step-spec_gate: #c2a13f;
  --step-version_analyze: #a87fc4;
  --step-commit: #79a83f;
  --step-summarize: #828b98;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--bg);
  color: var(--fg);
  font-family: "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
  font-size: 14px;
  display: flex;
  flex-direction: column;
}

h1, h2, h3 { font-weight: 600; }

/* -- top bar -------------------------------------------------------- */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
}

.topbar h1 { font-size: 16px; margin: 0; }

.topbar-right { display: flex; align-items: center; gap: 14px; }

/* -- topbar overflow menu (desktop side) ---------------------------- *
 * The overflow menu (hamburger + #nav-menu wrapper) is a mobile-portrait
 * affordance. To keep the desktop top bar byte-for-byte unchanged, the only
 * rules that touch it on wide screens live here, scoped to >600px so they can
 * never apply to a phone: the wrapper is made transparent (`display: contents`)
 * so its children stay inline flex items of .topbar-right exactly as before,
 * and the hamburger toggle is hidden. The collapse/expand dropdown styling is
 * authored entirely inside the @media (max-width: 600px) block at end-of-file. */
@media (min-width: 601px) {
  .nav-menu { display: contents; }
  .nav-menu-toggle { display: none; }
  /* The Flows-pane "back to machines" button is a mobile-only affordance for
   * the single-view panel switch; on desktop both panes render side by side,
   * so it is hidden here (scoped >600px to never touch a phone). */
  .flows-back-btn { display: none; }
  /* The History detail-pane "back to sessions" button is a mobile-only
   * affordance for the single-view panel switch (G5); on desktop both History
   * panes show side by side, so it is hidden here (scoped >600px to never
   * touch a phone). */
  .history-back-btn { display: none; }
  /* The flow-view sidebar drawer toggle + its backdrop are mobile-only (G4):
   * on desktop the sidebar is always part of the grid, so both are hidden
   * here (scoped >600px to never touch a phone). */
  .flow-sidebar-toggle,
  .flow-sidebar-backdrop { display: none; }
}

.conn {
  font-size: 12px;
  padding: 3px 9px;
  border-radius: 10px;
  border: 1px solid var(--border);
}
.conn-connected    { color: var(--green);  border-color: var(--green); }
.conn-connecting   { color: var(--yellow); border-color: var(--yellow); }
.conn-disconnected { color: var(--red);    border-color: var(--red); }

.se3-version {
  font-size: 11px;
  color: var(--fg-dim);
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
}
.se3-version:empty { display: none; }

button {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 7px 13px;
  border-radius: 5px;
  font-family: inherit;
  font-size: 13px;
  cursor: pointer;
}
button:hover:not(:disabled) { filter: brightness(1.12); }
button:disabled { opacity: 0.5; cursor: not-allowed; }

.icon-btn {
  background: transparent;
  color: var(--fg-dim);
  font-size: 20px;
  line-height: 1;
  padding: 0 6px;
}

/* -- layout --------------------------------------------------------- */

.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(200px, 280px) 1fr;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
}

.machines-pane, .flows-pane {
  background: var(--bg);
  padding: 14px 16px;
  overflow-y: auto;
}

.machines-pane h2, .flows-pane h2 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-dim);
  margin: 0 0 10px;
}

@media (max-width: 720px) {
  .layout { grid-template-columns: 1fr; grid-auto-rows: min-content 1fr; }
}

/* -- machine list --------------------------------------------------- */

.machine-list { list-style: none; margin: 0; padding: 0; }

.machine-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 9px;
  border-radius: 5px;
  cursor: pointer;
  margin-bottom: 3px;
}
.machine-item:hover { background: var(--bg-raised); }
.machine-item.selected { background: var(--bg-card); }

.dot {
  width: 9px; height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--grey);
}
.dot.online  { background: var(--green); box-shadow: 0 0 6px var(--green); }
.dot.offline { background: var(--grey); }

.machine-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.machine-count { color: var(--fg-dim); font-size: 12px; }

/* -- flow cards ----------------------------------------------------- */

.flow-list { display: flex; flex-direction: column; gap: 10px; }

.flow-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 11px 13px;
  cursor: pointer;
}
.flow-card:hover { border-color: var(--accent); }

.flow-card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
}
.flow-task {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  font-size: 11px;
  padding: 2px 7px;
  border-radius: 9px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.badge-running   { background: rgba(76,141,255,.2); color: var(--accent); }
.badge-completed { background: rgba(76,175,106,.2); color: var(--green); }
.badge-failed    { background: rgba(224,86,75,.2);  color: var(--red); }
.badge-paused    { background: rgba(214,162,58,.2); color: var(--yellow); }
.badge-init,
.badge-unknown   { background: rgba(106,107,112,.2); color: var(--fg-dim); }

.badge-call {
  background: var(--yellow);
  color: #1a1b1e;
  font-weight: 600;
  cursor: pointer;
}

/* Resume button — inline inside flow cards, history items, and the sidebar. */
.btn-resume {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 2px 10px;
  border-radius: 9px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  margin-left: 6px;
  flex-shrink: 0;
}
.btn-resume:hover:not(:disabled) { filter: brightness(1.15); }
.btn-resume:disabled { opacity: 0.5; cursor: not-allowed; }

/* Resume bar injected below the history detail title. */
.history-resume-bar {
  margin: 4px 0 8px;
}

.progress {
  height: 6px;
  background: var(--bg-raised);
  border-radius: 3px;
  overflow: hidden;
}
.progress-bar { height: 100%; background: var(--accent); transition: width .3s; }

.flow-meta {
  display: flex;
  justify-content: space-between;
  color: var(--fg-dim);
  font-size: 12px;
  margin-top: 6px;
}

/* -- running-flow chat view ----------------------------------------- */
/*
 * A full-screen view (parity with the history view): a sidebar carries
 * Overview / Steps / Machine, the conversation is the scrollable main body,
 * intervention items are pinned above a docked reply box.
 */

.flow-view {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 25;
  display: flex;
  flex-direction: column;
}
.flow-view-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--bg-raised);
  border-bottom: 1px solid var(--border);
}
.flow-view-head h3 {
  margin: 0;
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.flow-view-body {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(220px, 320px) 1fr;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
}
.flow-sidebar {
  background: var(--bg);
  padding: 14px 16px;
  overflow-y: auto;
}
.flow-sidebar-content { display: flex; flex-direction: column; gap: 16px; }

/* Main column: conversation scrolls, interventions + reply box are docked. */
.flow-main {
  background: var(--bg);
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}
.flow-conversation {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 14px 16px;
}
/*
 * .flow-conversation reuses .history-detail's flex-column layout. In a flex
 * column children default to `flex-shrink: 1`, which compresses each step
 * block to make the whole stack fit one viewport — combined with
 * .history-step's `overflow: hidden` (kept for rounded corners), that
 * silently crops every step's body to a thin strip. Pin children to their
 * natural height so the .flow-conversation scroller is the one that grows.
 */
.flow-conversation > .history-step,
.flow-conversation > .conv-record,
.flow-conversation > p,
.flow-conversation > div {
  flex-shrink: 0;
}

/* Session token/cost total badge (G4): docked as a non-scrolling thin strip
 * between the conversation and the reply box, with the pill pinned to the
 * left. Deliberately low-key — small dim text, no fill — so it reads as a
 * footnote/角标 and neither obscures the conversation scroll area nor competes
 * with the docked reply controls. Hidden entirely until usage is non-zero. */
.flow-usage-badge {
  flex: 0 0 auto;
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 3px 16px 4px;
  background: var(--bg);
  border-top: 1px solid var(--border);
  color: var(--fg-dim);
  font-size: 11px;
  line-height: 1.4;
}
.flow-usage-badge.hidden { display: none; }
.flow-usage-badge__label {
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.8;
}
.flow-usage-badge__value {
  font-variant-numeric: tabular-nums;
  word-break: break-word;
}

/* -- agent/model badge --------------------------------------------- */
/*
 * A small, unobtrusive badge at the top of assistant conversation bubbles
 * showing which agent produced the response. Displays "agentName · modelName"
 * when both are present, or just "agentName" when only the agent is known.
 * Shown ONLY when the record carries an agent_name field — old records
 * without this field render nothing, no placeholder.
 */
.agent-badge {
  display: inline-block;
  padding: 2px 8px;
  background: var(--bg-alt, #f0f0f0);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--fg-dim);
  font-size: 11px;
  line-height: 1.4;
  margin-bottom: 6px;
  white-space: nowrap;
}

@media (max-width: 720px) {
  .flow-view-body {
    grid-template-columns: 1fr;
    grid-auto-rows: min-content 1fr;
  }
}

/* -- intervention chip-bar ------------------------------------------ */
/*
 * Pending interventions appear inside the docked reply form as a horizontal,
 * wrap-friendly bar of compact chips (kind icon + label + optional short call
 * id). Clicking a chip selects it; the full prompt / context / options for the
 * selected chip materialize in the reply-context panel below the bar.
 */

.flow-interventions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
}
.flow-interventions:empty { display: none; }

.intervention-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid var(--yellow);
  border-radius: 14px;
  background: rgba(214, 162, 58, 0.12);
  color: var(--fg);
  font: inherit;
  font-size: 11.5px;
  cursor: pointer;
}
.intervention-chip:hover:not(:disabled) { filter: brightness(1.12); }
.intervention-chip.selected {
  box-shadow: 0 0 0 2px rgba(214, 162, 58, 0.55);
}
.intervention-chip.kind-interjection {
  border-color: var(--accent);
  background: rgba(76, 141, 255, 0.12);
}
.intervention-chip.kind-interjection.selected {
  box-shadow: 0 0 0 2px rgba(76, 141, 255, 0.55);
}
.intervention-chip.kind-retry_decision {
  border-color: var(--red);
  background: rgba(224, 86, 75, 0.12);
}
.intervention-chip.kind-retry_decision.selected {
  box-shadow: 0 0 0 2px rgba(224, 86, 75, 0.55);
}
.intervention-chip.kind-discovery_confirm {
  border-color: var(--green);
  background: rgba(76, 175, 106, 0.12);
}
.intervention-chip.kind-discovery_confirm.selected {
  box-shadow: 0 0 0 2px rgba(76, 175, 106, 0.55);
}
/* Lifecycle states for interjection chips: `pending` (interjection has been
 * sent to the daemon and is queued for the running flow to drain) and
 * `consumed` (the running flow has drained it). Driven by ws
 * `interjection_event` phase messages — see applyInterjectionEvent in app.js.
 * Both states are purely visual; click + selection still work normally. */
.intervention-chip.state-pending {
  border-style: dashed;
  background: rgba(76, 141, 255, 0.22);
  animation: chip-pending-pulse 1.6s ease-in-out infinite;
}
.intervention-chip.state-consumed {
  opacity: 0.55;
  text-decoration: line-through;
  background: rgba(76, 175, 106, 0.14);
  border-color: var(--green);
}
@keyframes chip-pending-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(76, 141, 255, 0.25); }
  50%      { box-shadow: 0 0 0 4px rgba(76, 141, 255, 0.10); }
}
.intervention-chip-icon { font-size: 13px; }
.intervention-chip-label {
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 10.5px;
}
.intervention-chip-callid {
  color: var(--fg-dim);
  font-size: 10.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 12ch;
}

/* Interjection lifecycle phases (G4 task 2). Driven by `interjection_event`
 * pushes from the server. `state-pending` is the active "waiting for the
 * flow to consume" state — a subtle dashed border + faint pulse animation;
 * `state-consumed` is a final "the flow has consumed this" state — muted
 * fill so the just-consumed chip lingers visibly for a frame before the
 * snapshot drops it. */
@keyframes interjection-pending-pulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.72; }
}
.intervention-chip.state-pending {
  border-style: dashed;
  animation: interjection-pending-pulse 1.4s ease-in-out infinite;
}
.intervention-chip.state-consumed {
  opacity: 0.55;
  filter: grayscale(0.55);
  text-decoration: line-through;
  text-decoration-color: rgba(0, 0, 0, 0.35);
}

/* -- docked reply box ----------------------------------------------- */

.flow-reply {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 16px 12px;
  background: var(--bg-raised);
  border-top: 1px solid var(--border);
}
.flow-reply-context {
  font-size: 12px;
  color: var(--fg-dim);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.flow-reply-context.active { color: var(--fg); }

.flow-reply-empty,
.flow-reply-hint {
  margin: 0;
  font-size: 11.5px;
  color: var(--fg-dim);
  font-style: italic;
}

.flow-reply-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}
.flow-reply-to {
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 10.5px;
  color: var(--fg-dim);
}
.flow-reply-kind {
  font-weight: 600;
  color: var(--yellow);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 11px;
}
.flow-reply-kind.kind-interjection { color: var(--accent); }
.flow-reply-kind.kind-retry_decision { color: var(--red); }
.flow-reply-kind.kind-discovery_confirm { color: var(--green); }
.flow-reply-callid {
  color: var(--fg-dim);
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Default-collapsed prompt body in the docked reply panel. The trigger toggles
 * the body's `.hidden` (display:none) state; when expanded the body is capped at
 * 30vh and scrolls internally so a very long prompt (e.g. a discovery_confirm
 * embedding the whole refined task description) can never push the textarea /
 * options / Send button out of view. */
.flow-reply-prompt-wrap { display: flex; flex-direction: column; gap: 5px; }
.flow-reply-prompt-toggle {
  align-self: flex-start;
  padding: 2px 9px;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--fg-dim);
  font: inherit;
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  cursor: pointer;
}
.flow-reply-prompt-toggle:hover { border-color: var(--fg-dim); color: var(--fg); }
.flow-reply-prompt-wrap.expanded .flow-reply-prompt-toggle {
  color: var(--yellow);
  border-color: var(--yellow);
}

.flow-reply-prompt {
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--fg);
  /* Expanded state: bound the height and scroll internally so the prompt body
   * cannot grow the docked bar without limit. Long single-line content wraps
   * (Long-Content Wrapping convention) rather than producing a horizontal
   * scrollbar. */
  max-height: 30vh;
  overflow-y: auto;
  overflow-x: hidden;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.flow-reply-prompt .md-p { margin: 4px 0; }
.flow-reply-prompt .md-p:first-child { margin-top: 0; }
.flow-reply-prompt .md-p:last-child { margin-bottom: 0; }

.flow-reply-context-block { display: flex; flex-direction: column; gap: 3px; }
.flow-reply-context-label {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--fg-dim);
}
.flow-reply-context-body {
  margin: 0;
  padding: 7px 9px;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 5px;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: inherit;
  font-size: 11.5px;
  color: var(--fg-dim);
}

.flow-reply-options {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.flow-reply-option {
  padding: 3px 11px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--accent);
  font-size: 11.5px;
}
.flow-reply-option:hover:not(:disabled) {
  border-color: var(--accent);
  background: var(--bg-card);
}
.flow-reply-option-primary {
  border-color: var(--green);
  color: var(--green);
  font-weight: 600;
}
.flow-reply-option-primary:hover:not(:disabled) {
  border-color: var(--green);
  background: rgba(76, 175, 106, 0.12);
}

.flow-reply-row {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 8px;
}
.flow-reply-row textarea {
  flex: 1 1 220px;
  min-width: 0;
  resize: vertical;
  min-height: 120px;
}
.flow-reply-row textarea:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
#flow-reply-submit { flex-shrink: 0; align-self: flex-end; }

/* Small icon button used at the left end of the reply row (Interject) and
 * symmetric to the Send button on the right. */
.reply-icon-btn {
  flex-shrink: 0;
  align-self: flex-end;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  min-height: 38px;
  padding: 0;
  background: transparent;
  color: var(--fg-dim);
  border: 1px solid var(--border);
  border-radius: 5px;
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
}
.reply-icon-btn:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--fg);
  background: var(--bg-card);
}
.reply-icon-btn.interject.active {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(76, 141, 255, 0.12);
}

@media (max-width: 480px) {
  .flow-reply-row textarea { flex-basis: 100%; }
  #flow-reply-submit { align-self: flex-end; }
}

/* -- collapsed prompt chips ----------------------------------------- */
/*
 * user / system template-style messages render as a one-line clickable chip
 * by default; clicking expands the full record without deleting any content.
 */

.msg-chip-wrap { width: 100%; }
.msg-chip {
  display: block;
  width: 100%;
  text-align: left;
  padding: 5px 10px;
  background: var(--bg-card);
  border: 1px dashed var(--border);
  border-radius: 6px;
  color: var(--fg-dim);
  font: inherit;
  font-size: 11.5px;
  text-transform: lowercase;
  letter-spacing: 0.02em;
  cursor: pointer;
}
.msg-chip:hover { border-color: var(--accent); color: var(--fg); }
.msg-chip-wrap.collapsed .msg-chip-detail { display: none; }
.msg-chip-detail { margin-top: 6px; }

.detail-section { margin-bottom: 16px; }
.detail-section h4 {
  font-size: 12px;
  text-transform: uppercase;
  color: var(--fg-dim);
  margin: 0 0 7px;
}

.step-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
  border-bottom: 1px dotted var(--border);
}
.step-icon { width: 16px; text-align: center; }
.step-icon.completed { color: var(--green); }
.step-icon.failed    { color: var(--red); }
.step-icon.running   { color: var(--accent); }
.step-icon.paused,
.step-icon.pending   { color: var(--fg-dim); }
.step-name { flex: 1; }
.step-dur { color: var(--fg-dim); font-size: 12px; }

.kv { display: flex; gap: 8px; padding: 2px 0; }
.kv .k { color: var(--fg-dim); min-width: 110px; }

/* -- modal ---------------------------------------------------------- */

.modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.55);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 30;
}
.modal-card {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: 9px;
  width: min(480px, 92vw);
  max-height: 90vh;
  overflow-y: auto;
}
.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
}
.modal-head h3 { margin: 0; font-size: 14px; }
.modal-body { padding: 14px 16px; display: flex; flex-direction: column; }

.modal-body label {
  font-size: 12px;
  color: var(--fg-dim);
  margin: 10px 0 4px;
}

select, textarea, input {
  background: var(--bg);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 7px 8px;
  font-family: inherit;
  font-size: 13px;
}
textarea { resize: vertical; }
select:focus, textarea:focus { outline: 1px solid var(--accent); }

.modal-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 14px;
}

.form-error {
  color: var(--red);
  font-size: 12px;
  margin: 8px 0 0;
}

.form-hint {
  color: var(--fg-dim);
  font-size: 11.5px;
  font-style: italic;
  margin: 4px 0 0;
}

#nt-project-manual { margin-top: 6px; font-family: ui-monospace, monospace; }
#nt-project-manual.hidden { display: none; }

.modal-body label.checkbox-label {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 7px;
  margin: 12px 0 2px;
  color: var(--fg);
  cursor: pointer;
}
.modal-body label.checkbox-label input {
