  margin: 0;
}

/* -- history view --------------------------------------------------- */

.ghost-btn {
  background: transparent;
  color: var(--fg);
  border: 1px solid var(--border);
}
.ghost-btn:hover:not(:disabled) { border-color: var(--accent); filter: none; }

/* -- issues view ----------------------------------------------------- */

.issues-view {
