.issues-list { display: flex; flex-direction: column; gap: 8px; }

/* Issues toolbar: filters + create button */
.issues-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding-bottom: 8px;
  margin-bottom: 4px;
