/* Issue badges */
.badge-open         { background: rgba(214,162,58,.2); color: var(--yellow); }
.badge-in-progress  { background: rgba(76,141,255,.2); color: var(--accent); }
.badge-resolved     { background: rgba(76,175,106,.2); color: var(--green); }
.badge-wontfix      { background: rgba(106,107,112,.2); color: var(--grey); }
.badge-closed       { background: rgba(106,107,112,.15); color: var(--fg-dim); }

/* Priority badges */
