  word-break: break-word;
}
.issue-detail-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 4px;
}
.issue-detail-actions .ghost-btn {
  padding: 5px 12px;
  font-size: 12px;
}

/* Issue-row "启动 flow" entry: a compact action under the meta line. */
.issue-item-actions {
