  gap: 8px;
  margin-top: 6px;
}
.issue-launch-btn {
  padding: 3px 10px;
  font-size: 11px;
}
.issue-launch-btn.disabled,
.issue-launch-btn:disabled {
  opacity: .45;
  cursor: not-allowed;
}

/* Form row for side-by-side fields */
.form-row {
  display: flex;
  gap: 12px;
}
.form-col {
  flex: 1;
  display: flex;
  flex-direction: column;
}
.form-col label { margin-bottom: 4px; }
.required { color: var(--red); }

/* Small modal variant */
.modal-card-sm { max-width: 420px; }

/* Desktop: hide the issues back button */
@media (min-width: 601px) {
  .issues-back-btn { display: none; }
}

.history-view {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 25;
  display: flex;
  flex-direction: column;
}
.history-head {
  display: flex;
  align-items: center;
