  grid-template-columns: minmax(220px, 320px) 1fr;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
}
.history-list-pane, .history-detail-pane {
  background: var(--bg);
  padding: 14px 16px;
  overflow-y: auto;
}
.history-list-pane h4, .history-detail-pane h4 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-dim);
  margin: 0 0 10px;
}
.history-detail-pane h4 {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 720px) {
  .history-body { grid-template-columns: 1fr; grid-auto-rows: min-content 1fr; }
}

.history-list { display: flex; flex-direction: column; gap: 8px; }

/* Project select dropdown prepended to the history list when sessions span
 * multiple project_roots. A single horizontal row with a label and a native
 * <select>, styled to match the New Task form's Project dropdown. */
.history-project-select-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding-bottom: 6px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--border);
}
.history-project-select-label {
  font-size: 12px;
  color: var(--fg-dim);
  flex: 0 0 auto;
}
.history-project-select {
  flex: 1 1 auto;
  max-width: 100%;
  background: var(--bg);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 5px 8px;
  font-family: inherit;
  font-size: 13px;
}

/* Lightweight "refreshing" bar prepended to a non-empty list while the
 * /api/history round-trip is in flight (the empty-list case reuses .empty). */
.history-refreshing {
  color: var(--fg-dim);
  font-size: 12px;
  padding: 4px 2px;
  margin: 0;
}

.history-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 9px 11px;
  cursor: pointer;
}
.history-item:hover { border-color: var(--accent); }
.history-item.selected { border-color: var(--accent); background: var(--bg-raised); }

.history-item-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 6px;
}
.history-task {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.history-item-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: var(--fg-dim);
  font-size: 11px;
