2060	.history-detail .conv-record.step-type-summarize:not(.step-status-row):not(.group-status-marker) {
2061	  border-left-color: var(--step-summarize);
2062	  --step-lane: rgba(130, 139, 152, 0.09);
2063	}
2064	
2065	/*
2066	 * Continuous step "lane" background (方案A: 背景连续、块仍分明).
2067	 *
2068	 * Each content-type step-type record paints its --step-lane colour through a
2069	 * z-index:-1 ::before underlay that overflows ±7px vertically. Because
2070	 * .history-detail uses gap:14px between sibling records, two adjacent records
2071	 * of the SAME step each overflow 7px into the 14px gap and meet edge-to-edge
2072	 * at the gap mid-line, so the lane colour reads as one continuous band across
2073	 * the whole step region instead of a stack of disconnected islands. The
2074	 * records' own bubbles / cards / tool markers keep their borders and higher-
2075	 * alpha backgrounds untouched, so the blocks stay individually distinct.
2076	 *
2077	 * Status / DAG markers (.step-status-row / .group-status-marker) are excluded,
2078	 * exactly as the per-type colour rules above.
2079	 */
2080	.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {
2081	  position: relative;
2082	}
2083	.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before {
2084	  content: "";
2085	  position: absolute;
2086	  left: 0;
2087	  right: 0;
2088	  top: -7px;
2089	  bottom: -7px;
2090	  z-index: -1;
2091	  pointer-events: none;
2092	  background-color: var(--step-lane);
2093	}
2094	
2095	/*
2096	 * Boundary & container-edge suppression. The ±7px overflow must stay strictly
2097	 * INSIDE one step region: it must never cross a .history-step-header into a
2098	 * neighbouring step, nor bleed into the conversation area's top/bottom padding.
2099	 * This keeps the step-to-step boundary visually identical to before.
2100	 *
2101	 * - First block of a step (right after a header): no upward overflow.
2102	 * - Last block of a step (right before the next header): no downward overflow.
2103	 * - First / last child of the container: no overflow past the container edge.
2104	 *
2105	 * Degrades gracefully where :has() is unsupported: only a 7px same-step tail
2106	 * remains below a step's last block — still never crossing into the next step.
2107	 *
2108	 * Specificity note: the base ::before underlay rule above carries
2109	 * `[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)`,
2110	 * giving it specificity (0,5,1). A naive boundary selector such as
2111	 * `.history-detail .history-step-header + .conv-record::before` is only
2112	 * (0,3,1), so its `top:0` / `bottom:0` would LOSE the cascade and the
2113	 * ±7px overflow would stand — bleeding the lane colour across the step
2114	 * boundary. We therefore repeat the `.history-detail` class (a no-op for
2115	 * matching — an element either has the class or not) to lift each boundary
2116	 * rule to (0,5,1), equal to the base rule; since these rules come later in
2117	 * source order, they win the tie and correctly reset the overflow to 0.
2118	 */
2119	.history-detail.history-detail.history-detail .history-step-header + .conv-record::before { top: 0; }
2120	.history-detail.history-detail.history-detail .conv-record:has(+ .history-step-header)::before { bottom: 0; }
2121	.history-detail.history-detail.history-detail > .conv-record:first-child::before { top: 0; }
2122	.history-detail.history-detail.history-detail > .conv-record:last-child::before { bottom: 0; }
2123	
2124	/* The step-header separator row is the explicit boundary between two step
2125	 * regions. Give it a little extra breathing room above (never before the very
2126	 * first header) so the colour change between lanes is unmistakable; the title
2127	 * keeps its existing reverse-block look. Scoped to the conversation so the
2128	 * history LIST is untouched. */
2129	.history-detail .history-step-header { margin-top: 4px; }
2130	.history-detail .history-step-header:first-child { margin-top: 0; }
2131	
2132	/* -- step report card ----------------------------------------------- */
2133	/*
2134	 * Default-expanded report card mirroring the CLI's per-step Rich Panel.
2135	 * Sits inside the .history-step container directly after the raw
2136	 * step_completed chip. No max-height — long reports scroll with the
2137	 * page, not inside a captive viewport (see the running-flow-console
2138	 * spec: per-block height caps are not allowed).
2139	 */
2140	.step-report {
