check("G2 step-type record establishes a positioning context", () => {
  const body = ruleBody(
    CSS,
    `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {`);
  assert.ok(/position:\s*relative/.test(body),
