.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {
  position: relative;
  /*
   * Establish a stacking context on the record itself. Without this, the
   * z-index:-1 ::before underlay below would NOT be contained by .conv-record
   * (which is merely position:relative) and would instead resolve against the
   * nearest ancestor that DOES form a stacking context (.history-view /
   * #flow-view). The intervening panes (.history-detail-pane / .flow-main)
   * carry an opaque `background: var(--bg)` that paints OVER a negative-z
   * descendant pseudo, hiding the lane tint entirely. `isolation: isolate`
   * forms a stacking context with no other side effects, so the underlay
   * paints behind the record's own content but ABOVE the pane background,
   * keeping the lane colour visible.
   */
  isolation: isolate;
}
.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: -7px;
  bottom: -7px;
  z-index: -1;
  pointer-events: none;
  background-color: var(--step-lane);
}

/*
 * Boundary & container-edge suppression. The ±7px overflow must stay strictly
 * INSIDE one step region: it must never cross a .history-step-header into a
 * neighbouring step, nor bleed into the conversation area's top/bottom padding.
 * This keeps the step-to-step boundary visually identical to before.
 *
 * - First block of a step (right after a header): no upward overflow.
 * - Last block of a step (right before the next header): no downward overflow.
 * - First / last child of the container: no overflow past the container edge.
 *
 * Degrades gracefully where :has() is unsupported: only a 7px same-step tail
 * remains below a step's last block — still never crossing into the next step.
 *
 * Specificity note: the base ::before underlay rule above carries
 * `[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)`,
 * giving it specificity (0,5,1). A naive boundary selector such as
 * `.history-detail .history-step-header + .conv-record::before` is only
 * (0,3,1), so its `top:0` / `bottom:0` would LOSE the cascade and the
 * ±7px overflow would stand — bleeding the lane colour across the step
 * boundary. We therefore repeat the `.history-detail` class (a no-op for
 * matching — an element either has the class or not) to lift each boundary
 * rule to (0,5,1), equal to the base rule; since these rules come later in
 * source order, they win the tie and correctly reset the overflow to 0.
 */
.history-detail.history-detail.history-detail .history-step-header + .conv-record::before { top: 0; }
.history-detail.history-detail.history-detail .conv-record:has(+ .history-step-header)::before { bottom: 0; }
.history-detail.history-detail.history-detail > .conv-record:first-child::before { top: 0; }
.history-detail.history-detail.history-detail > .conv-record:last-child::before { bottom: 0; }

