check("G2 step first block does not overflow upward across the header", () => {
  const body = ruleBody(
    CSS, ".history-detail .history-step-header + .conv-record::before");
  assert.ok(/top:\s*0/.test(body), "first block ::before must reset top to 0");
});
check("G2 step last block does not overflow downward across the next header", () => {
  const body = ruleBody(
    CSS, ".history-detail .conv-record:has(+ .history-step-header)::before");
  assert.ok(/bottom:\s*0/.test(body), "last block ::before must reset bottom to 0");
});
check("G2 container first/last child does not overflow past the edge", () => {
  const firstBody = ruleBody(
    CSS, ".history-detail > .conv-record:first-child::before");
  assert.ok(/top:\s*0/.test(firstBody), "first child ::before must reset top to 0");
  const lastBody = ruleBody(
    CSS, ".history-detail > .conv-record:last-child::before");
  assert.ok(/bottom:\s*0/.test(lastBody), "last child ::before must reset bottom to 0");
});

